/* ============================================================
   CUSTOMERS
   ============================================================ */
let custQ="";
function renderCustomers(){
  const q=custQ.toLowerCase(); const rows=S.customers.filter(c=>!q||[c.name,c.phone,c.email,c.address].join(" ").toLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name));
  return `<div class="topbar"><h1>Customers</h1><input type="search" id="q_custQ" placeholder="Search name, phone, address…" value="${esc(custQ)}" oninput="custQ=this.value;render()" style="max-width:300px">${isManager()?dd("More",[["Export customers (CSV)","exportCSV('customers')"]]):""}<button class="btn p" onclick="editCustomer()">Add customer</button></div>
  <div class="card">${table(rows,[["Name",c=>`<a href="#" onclick="openCustomer('${c.id}');return false"><b>${esc(c.name)}</b></a>${c.company?`<div class="small">${esc(c.company)}</div>`:""}<div class="muted">${esc(c.phone||"")} ${esc(c.email||"")}${c.referral?" · via "+esc(c.referral):""}</div>`],["Address",c=>`${esc(c.address||"")}<div class="muted">${c.lat?`pinned`:'<span class="tag warn">no map pin</span>'}${c.taxExempt?' · <span class="tag info">tax exempt</span>':""}${c.credit>0?` · <span class="tag ok">credit ${money(c.credit)}</span>`:""}</div>`],["Lifetime",c=>money(S.invoices.filter(i=>i.customerId===c.id&&!["void","quote"].includes(i.status)).reduce((a,i)=>a+invTotals(i).total,0)),"n"],["Last visit",c=>{const l=S.invoices.filter(i=>i.customerId===c.id).map(i=>i.date).sort().pop();return l?dateShort(l):"—"}],["",c=>`<button class="btn s" onclick="editCustomer('${c.id}')">Edit</button>`]],"No customers yet. They're added at the register or here.")}</div>`;
}
function editCustomer(id,after,reason){
  const c=byId("customers",id)||{name:"",phone:"",email:"",address:"",lat:"",lng:"",notes:"",prefStart:"09:00",prefEnd:"17:00",taxExempt:false,sleepNotes:""};
  const req=storeSettings().requireCustomer!==false; const star=req?' <span style="color:var(--red)">*</span>':"";
  const refs=referralSources(); const refKnown=refs.includes(c.referral||""); const star2=' <span style="color:var(--red)">*</span>';
  const fn=c.first!==undefined?c.first:(c.company&&c.name===c.company?"":String(c.name||"").split(" ")[0]), ln=c.last!==undefined?c.last:(c.company&&c.name===c.company?"":String(c.name||"").split(" ").slice(1).join(" "));
  modal(`<h2>${id?"Edit customer":"New customer"}</h2>${reason?`<div class="notice">${esc(reason)}</div>`:""}
  <div class="grid g3"><div class="field"><label class="f" id="c_first_lbl">First name${star2}</label><input type="text" id="c_first" value="${esc(fn)}" autofocus oninput="fmtName(this)" autocapitalize="words"></div><div class="field"><label class="f" id="c_last_lbl">Last name${star2}</label><input type="text" id="c_last" value="${esc(ln)}" oninput="fmtName(this)" autocapitalize="words"></div><div class="field"><label class="f">Mobile phone${star2}</label><input type="tel" id="c_phone" value="${esc(c.phone)}" required oninput="fmtPhone(this)" placeholder="555-555-5555" inputmode="numeric"></div></div>
  <div class="row" style="margin:-4px 0 8px"><label class="chk small" style="margin:0"><input type="checkbox" id="c_isbiz" ${c.company?"checked":""} onchange="document.getElementById('c_bizbox').style.display=this.checked?'':'none';if(!this.checked){document.getElementById('c_company').value='';}custNameLabels()"> This is a business / company account</label></div>
  <div id="c_bizbox" class="field" style="${c.company?"":"display:none"}"><label class="f">Company / business name <span class="muted">(the name above becomes the business contact)</span></label><input type="text" id="c_company" value="${esc(c.company||"")}" placeholder="e.g. Meadow Ridge Assisted Living" oninput="custNameLabels()"></div>
  <div class="grid g2"><div class="field" style="grid-column:span 2"><label class="f" ${storeSettings().askReferral==="off"?'style="display:none"':""}>How did they hear about us?${storeSettings().askReferral==="required"?star2:""}</label><select id="c_ref" onchange="document.getElementById('c_refother').style.display=this.value==='Other'?'':'none'">${optsList(refs,refKnown?c.referral:(c.referral?"Other":""),"Choose…")}</select><input type="text" id="c_refother" value="${esc(refKnown||!c.referral?"":c.referral)}" placeholder="Type the source…" style="margin-top:4px;${(!refKnown&&c.referral)||c.referral==="Other"?"":"display:none"}"></div></div>
  <div class="field"><label class="f">Email</label><input type="email" id="c_email" value="${esc(c.email)}"></div>${addrFields("c_addr",c)}<details style="margin:8px 0 4px" ${c.idPhoto||c.idScan||c.trusted||c.lat||c.deliveryNotes||c.sleepNotes||c.taxExempt||c.taxRate?"open":""}><summary style="cursor:pointer;font-weight:700;color:var(--ink2)">More details <span class="muted small" style="font-weight:500">— ID on file, delivery notes, map pin, home hours, tax, sleep preferences</span></summary><div style="margin-top:8px">${idPanelHTML(c)}${has("approve")?`<label class="chk" style="margin:6px 0"><input type="checkbox" id="c_trusted" ${c.trusted?"checked":""}> Trusted repeat customer — skip the same-day card / ID cautions on their sales (logged)</label>`:(c.trusted?`<p class="small" style="margin:6px 0"><span class="tag ok">Trusted repeat customer</span></p>`:"")}${id?`<p class="small" style="margin:6px 0">Store credit on account: <b>${money(c.credit||0)}</b>${has("credit")?` · <a href="#" onclick="adjustCredit('${id}');return false">Adjust…</a>`:""}</p>`:""}
  <div class="field"><label class="f">Map pin — paste coordinates or a Google Maps link</label><div class="row"><input type="text" id="c_coords" value="${c.lat?`${c.lat}, ${c.lng}`:""}" placeholder="40.4406, -79.9959"><a class="btn fx" target="_blank" rel="noopener" href="#" onclick="this.href=mapsSearchUrl(document.getElementById('c_addr').value)">Find on map</a></div><div class="muted small" style="margin-top:4px">Open the address in Google Maps, long-press the pin, copy the coordinates and paste here. Pins drive route optimization and turn-by-turn links for the crew.</div></div>
  <div class="grid g3"><div class="field"><label class="f">Usually home from</label><input type="time" id="c_ps" value="${c.prefStart||"09:00"}"></div><div class="field"><label class="f">until</label><input type="time" id="c_pe" value="${c.prefEnd||"17:00"}"></div><div class="field"><label class="f">Tax</label><select id="c_tax"><option value="0" ${!c.taxExempt&&!c.taxRate&&!c.taxBracketId?"selected":""}>Store default (${esc(defaultTax().name)} ${defaultTax().rate}%)</option>${taxBrackets().map(t=>`<option value="b:${t.id}" ${c.taxBracketId===t.id?"selected":""}>${esc(t.name)} ${t.rate}%</option>`).join("")}<option value="1" ${c.taxExempt?"selected":""}>Tax exempt</option><option value="2" ${c.taxRate?"selected":""}>Custom rate</option></select><input type="number" step="0.001" id="c_taxrate" value="${c.taxRate||""}" placeholder="Custom rate % (destination tax)" style="margin-top:4px"></div></div>
  <div class="grid g2"><div class="field"><label class="f">Delivery notes (stairs, gate code, elevator booking…)</label><textarea id="c_notes" rows="2">${esc(c.notes)}</textarea></div><div class="field"><label class="f">Sleep & preference notes</label><textarea id="c_sleep" rows="2" placeholder="Side sleeper, runs hot, prefers medium…">${esc(c.sleepNotes||"")}</textarea></div></div>
  </div></details>
  <div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="saveCustomer('${id||""}',${after?"true":"false"})">Save customer</button></div>`);
  setTimeout(custNameLabels,0); window._idPhoto=undefined; window._idPhotoBack=undefined; window._idScan=null; setTimeout(()=>{ try{ if(typeof attachGoogleAutocomplete==="function") attachGoogleAutocomplete("c_addr","c_coords"); }catch(e){} },60);
}
function adjustCredit(cid){ if(!requirePerm("credit","issue or edit store credit")) return; const c=byId("customers",cid); modal(`<h2>Adjust store credit — ${esc(c.name)}</h2><p class="muted">Credit normally comes from a return. Use this only for goodwill credit or a correction — it's logged with your name and the reason.</p><div class="grid g2"><div class="field"><label class="f">Current</label><input type="text" value="${money(c.credit||0)}" disabled></div><div class="field"><label class="f">New amount on account</label><input type="number" step="0.01" id="cr_new" value="${(c.credit||0).toFixed(2)}"></div></div><div class="field"><label class="f">Reason</label><input type="text" id="cr_why" placeholder="e.g. goodwill for late delivery, correction"></div><div class="actions"><button class="btn" onclick="closeModal();editCustomer('${cid}')">Cancel</button><button class="btn p" onclick="(async()=>{ const c=byId('customers','${cid}'); const nv=fnum('cr_new'); const why=fv('cr_why').trim(); if(!why) return toast('Give a reason.',true); const old=c.credit||0; c.credit=round2(nv); (c.creditLog=c.creditLog||[]).push({date:todayISO(),by:session.staffId,from:old,to:c.credit,why}); await save('customers',c); logAudit('customer_credit',c.name+': '+money(old)+' → '+money(c.credit)+' — '+why,{amount:c.credit-old}); closeModal(); editCustomer('${cid}'); toast('Store credit updated'); })()">Save</button></div>`); }
function custNameLabels(){ const co=(fv("c_company")||"").trim(); const f=document.getElementById("c_first_lbl"), l=document.getElementById("c_last_lbl"); if(f) f.innerHTML=co?"Business contact — first name":"First name <span style=\"color:var(--red)\">*</span>"; if(l) l.innerHTML=co?"Business contact — last name":"Last name <span style=\"color:var(--red)\">*</span>"; }
async function saveCustomer(id,after){
  const co=parseCoords(fv("c_coords"));
  const first=normName(fv("c_first")), last=normName(fv("c_last")), company=fv("c_company").trim(); const contact=[first,last].filter(Boolean).join(" "); const c0=byId("customers",id)||{};
  const c=Object.assign({},byId("customers",id)||{credit:0,createdBy:session.staffId,createdAt:todayISO()},{id:id||undefined,first,last,name:contact||company,street:readAddrFields("c_addr").street,city:readAddrFields("c_addr").city,state:readAddrFields("c_addr").state,zip:readAddrFields("c_addr").zip,phone:normPhone(fv("c_phone")),email:fv("c_email").trim(),address:readAddrFields("c_addr").address,lat:co?co.lat:"",lng:co?co.lng:"",prefStart:fv("c_ps"),prefEnd:fv("c_pe"),taxExempt:fv("c_tax")==="1",taxRate:fv("c_tax")==="2"?fnum("c_taxrate"):0,taxBracketId:fv("c_tax").startsWith("b:")?fv("c_tax").slice(2):"",trusted:document.getElementById("c_trusted")&&has("approve")?fchk("c_trusted"):!!c0.trusted,credit:c0.credit||0,idPhoto:window._idPhoto!==undefined?await storeImage("id-photos",id||"new",window._idPhoto):(c0.idPhoto||""),idPhotoBack:window._idPhotoBack!==undefined?await storeImage("id-photos",id||"new",window._idPhotoBack,2):(c0.idPhotoBack||""),idScan:window._idScan||c0.idScan||null,company:fv("c_company").trim(),referral:(fv("c_ref")==="Other"?(fv("c_refother").trim()||"Other"):fv("c_ref")),notes:fv("c_notes"),sleepNotes:fv("c_sleep")});
  if(!c.company&&!contact) return toast("First and last name are required (or enter a company name).",true); if(document.getElementById("c_trusted")&&has("approve")&&!!c0.trusted!==!!c.trusted) logAudit("customer_credit",`${c.name}: trusted customer ${c.trusted?"ON":"OFF"}`);  if(!c.phone) return toast("Phone number is required.",true); if(!c.address&&storeSettings().requireAddress==="always") return toast("Address is required.",true); if(!c.address&&cur&&cur.delivery&&cur.customerId===c.id) return toast("This sale is a delivery — add the address.",true); if(!c.referral&&storeSettings().askReferral==="required") return toast("Please choose how they heard about us.",true);
  await save("customers",c); closeModal(); if(after&&cur){ cur.customerId=c.id; applyCustomerTax(c); } render();
}
function openCustomer(id){
  const c=byId("customers",id); const inv=S.invoices.filter(i=>i.customerId===id).sort((a,b)=>b.date.localeCompare(a.date)); const del=S.deliveries.filter(d=>d.customerId===id); const rets=S.returns.filter(r=>r.customerId===id); const cl=S.claims.filter(x=>x.customerId===id); const fu=S.followups.filter(f=>f.customerId===id&&f.status==="open");
  const ev=[...inv.map(i=>({d:i.date,t:`${i.status==="quote"?"Quote":"Invoice"} <a href="#" onclick="openInvoice('${i.id}');return false">${esc(i.number)}</a> · ${money(invTotals(i).total)} ${statusTag(i.status)}`})),...del.filter(d=>d.date).map(d=>({d:d.date,t:`Delivery ${statusTag(d.status)} ${d.deliveredAt?"signed "+esc(d.receivedBy||""):""}`})),...rets.map(r=>({d:r.date,t:`Return ${esc(r.number)} · ${esc(r.reason)} · refund ${money(r.refundTotal)}`})),...cl.map(x=>({d:x.date,t:`Warranty claim ${esc(x.number)} · ${esc(x.issue)} ${statusTag(x.status)}`}))].sort((a,b)=>b.d.localeCompare(a.d));
  modal(`<h2>${esc(c.name)}${c.company?` <span class="muted" style="font-size:14px">· ${esc(c.company)}</span>`:""}${c.idPhoto||c.idScan?' <span class="tag ok" title="ID on file">ID ✓</span>':""}${c.trusted?' <span class="tag ok" title="Trusted repeat customer">Trusted</span>':""}</h2>${c.idPhoto||c.idPhotoBack?`<div class="row" style="gap:8px;margin:4px 0 8px">${c.idPhoto?`<a href="${esc(c.idPhoto)}" target="_blank" rel="noopener"><img src="${esc(c.idPhoto)}" style="height:90px;border-radius:8px;border:1px solid var(--line)" title="ID front"></a>`:""}${c.idPhotoBack?`<a href="${esc(c.idPhotoBack)}" target="_blank" rel="noopener"><img src="${esc(c.idPhotoBack)}" style="height:90px;border-radius:8px;border:1px solid var(--line)" title="ID back"></a>`:""}<span class="muted small">ID on file${c.idScan&&c.idScan.at?" · "+dateShort(c.idScan.at):""}</span></div>`:""}<p class="muted">${c.referral?"Heard about us via "+esc(c.referral)+" · ":""}${c.phone?`<a href="tel:${esc(c.phone)}">${esc(c.phone)}</a>`:""} ${c.phone?`· <a href="sms:${esc(c.phone)}">Text</a>`:""} ${c.email?`· <a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`:""}<br>${esc(c.address||"")}${c.lat?` · <a target="_blank" rel="noopener" href="${mapsSearchUrl(c.lat+","+c.lng)}">map</a>`:""}${c.credit>0?` · <span class="tag ok">store credit ${money(c.credit)}</span>`:""}</p>
  ${c.notes?`<p><b>Delivery:</b> ${esc(c.notes)}</p>`:""}${c.sleepNotes?`<p><b>Sleep notes:</b> ${esc(c.sleepNotes)}</p>`:""}
  ${fu.length?`<div class="notice">Open follow-ups: ${fu.map(f=>esc(f.type)+" ("+dateShort(f.due)+")").join(", ")}</div>`:""}
  <h3 style="margin:10px 0 8px">History</h3><div class="timeline">${ev.map(e=>`<div><span class="muted">${dateShort(e.d)}</span> — ${e.t}</div>`).join("")||`<div class="muted">No history yet.</div>`}</div>
  <div class="actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn" onclick="editCustomer('${id}')">Edit</button><button class="btn" onclick="newClaim('${id}')">Warranty claim</button><button class="btn p" onclick="cur=newInvoice();cur.customerId='${id}';cur.taxExempt=${!!c.taxExempt};closeModal();go('pos')">New sale</button></div>`,true);
}

/* ============================================================
   FOLLOW-UPS
   ============================================================ */
const FOLLOW_KEYS={"Delivery check-in":"checkin","Review request":"review","Sleep trial ending soon":"trial","Layaway payment due":"layaway","Special order arrived":"arrived","Ready for pickup":"ready","Pickup reminder":"pickupReminder","Quote follow-up":"quote","ETA check":"eta","Call back":"issues","Unhappy at delivery":"unhappy","ETA change — notify":"etaNotify"};
const FOLLOW_LABELS={checkin:"Delivery check-in call (3 days after delivery)",review:"Review request (14 days after delivery / pickup)",trial:"Sleep-trial ending reminder",layaway:"Layaway payment due",arrived:"Special order arrived — call the customer",ready:"Ready for pickup — notify the customer",pickupReminder:"Pickup reminder the day before",quote:"Quote follow-up (2 days)",eta:"ETA check before a promised date",issues:"Call back after a delivery issue or missed stop",unhappy:"Customer unhappy at delivery — call today",etaNotify:"ETA changed by the vendor — text the customer"};
function autoFollowOn(type){ const k=FOLLOW_KEYS[type]; if(!k) return true; const cfg=storeSettings().autoFollowups||{}; return cfg[k]!==false; }
async function addFollowup(customerId,invoiceId,type,note,due,force){ if(!customerId) return; if(!force&&!autoFollowOn(type)) return; if(S.followups.some(f=>f.status==="open"&&f.invoiceId===invoiceId&&f.type===type)) return; return save("followups",{id:uid(),customerId,invoiceId,type,note,due,status:"open",created:todayISO()}); }
function openFollowup(id){
  const f=byId("followups",id); const c=byId("customers",f.customerId); const inv=byId("invoices",f.invoiceId);
  const sms=c?.phone?`sms:${esc(c.phone)}?&body=${encodeURIComponent(followupText(f))}`:"";
  modal(`<h2>${esc(f.type)}</h2><p><b>${esc(c?.name||"")}</b>${inv?` · <a href="#" onclick="openInvoice('${inv.id}');return false">${esc(inv.number)}</a>`:""}<br><span class="muted">Due ${dateFmt(f.due)}</span></p><p>${esc(f.note)}</p>
  <div class="row" style="margin-bottom:10px">${c?.phone?`<a class="btn" href="tel:${esc(c.phone)}">Call</a><a class="btn" href="${sms}">Text</a>`:""}${c?.email?`<a class="btn" href="mailto:${esc(c.email)}?subject=${encodeURIComponent(f.type+" — "+storeSettings().name)}&body=${encodeURIComponent(followupText(f))}">Email</a>`:""}</div>
  <div class="field"><label class="f">Outcome / notes</label><textarea id="fu_notes" rows="2">${esc(f.outcome||"")}</textarea></div>
  <div class="actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn" onclick="(async()=>{const f=byId('followups','${id}');f.due=addDays(todayISO(),3);f.outcome=fv('fu_notes');await save('followups',f);closeModal();render()})()">Snooze 3 days</button><button class="btn p" onclick="(async()=>{const f=byId('followups','${id}');f.status='done';f.doneAt=todayISO();f.outcome=fv('fu_notes');f.by=session.staffId;await save('followups',f);closeModal();render()})()">Mark done</button></div>`);
}
const STALE_ON_COMPLETE=new Set(["Special order arrived","Ready for pickup","ETA change — notify","Pickup reminder","ETA check","Delivery check-in"]);
async function closeStaleFollowups(invId,reason){ const inv=byId("invoices",invId); if(!inv) return; const allDone=!inv.lines.some(lineOpen); for(const f of S.followups.filter(f=>f.status==="open"&&f.invoiceId===invId)){ if(allDone?STALE_ON_COMPLETE.has(f.type)||f.type==="Ready for pickup":(f.type==="Ready for pickup"||f.type==="Pickup reminder")&&!pickupOf(inv)){ f.status="done"; f.doneAt=todayISO(); f.outcome=reason||"Order completed"; await save("followups",f); } } }
async function doneFollowup(id){ const f=byId("followups",id); if(!f) return; f.status="done"; f.doneAt=todayISO(); f.doneBy=session.staffId; f.outcome=f.outcome||"Notified"; await save("followups",f); render(); }
function followupText(f){ const c=byId("customers",f.customerId); const st=storeSettings(); const n=firstName(c?.name); const map={"Delivery check-in":`Hi ${n}, it's ${st.name}. Just checking that everything arrived in great shape and you're loving it. Anything we can help with?`,"Sleep trial ending soon":`Hi ${n}, it's ${st.name}. Your ${st.trialNights}-night comfort trial is coming up soon — how's the new mattress feeling? If it isn't quite right, we can help with a comfort exchange.`,"Review request":`Hi ${n}, thanks again for choosing ${st.name}! If you have a moment, a quick review really helps our small team.`,"Special order arrived":`Hi ${n}, great news — your order at ${st.name} has arrived. Reply or call us to set up ${byId("invoices",f.invoiceId)?.delivery?"delivery":"pickup"}.`,"Layaway payment due":`Hi ${n}, a friendly reminder from ${st.name} that your layaway payment is due ${dateShort(f.due)}. Thank you!`,"ETA change — notify":`Hi ${n}, it's ${st.name}. Quick update on your order: ${f.note.replace(/^[^:]*: /,"").replace(/ Let the customer know\.$/,"")}. Thanks for your patience — we'll let you know as soon as it's in.`,"Ready for pickup":`Hi ${n}, good news — your order at ${st.name} is in and ready for pickup. Reply with a day that works and we'll have it staged.`}; return map[f.type]||`Hi ${n}, it's ${st.name}. ${f.note}`; }

/* ============================================================
   POS / INVOICE BUILDER
   ============================================================ */
let cur=null, showMargin=false, selLines=new Set(); let invFulfil="all";
function lastSaleCard(){ const inv=window.lastSaleId?byId("invoices",window.lastSaleId):null; if(!inv||(cur&&cur.lines.length)) return ""; const T=invTotals(inv); const d=deliveryOf(inv), pk=pickupOf(inv); return `<div class="card" style="margin-bottom:14px;border-left:4px solid var(--green)"><div class="row" style="gap:10px;align-items:center;flex-wrap:wrap"><div style="flex:1"><b>Sale completed — ${esc(inv.number)}</b> · ${esc(custDisplay(byId("customers",inv.customerId)))} · ${money(T.total)}${T.balance>0.005?` · <span class="tag bad">balance ${money(T.balance)}</span>`:` · <span class="tag ok">paid in full</span>`}<div class="muted small">${esc(fulfillmentLabel(inv))}. You can still change payments, details or paperwork from here.</div></div><div class="bgroup"><button class="btn s p" onclick="openInvoice('${inv.id}')">Open invoice</button>${T.balance>0.005?`<button class="btn s" onclick="payInvoice('${inv.id}')">Record payment</button>`:""}<button class="btn s" onclick="printInvoice(byId('invoices','${inv.id}'))">Print</button>${!inv.signature?`<button class="btn s" onclick="invoiceSign('${inv.id}')">Sign</button>`:""}${d&&d.status==="unscheduled"?`<button class="btn s" onclick="editDelivery('${d.id}')">Schedule delivery</button>`:""}${pk&&pk.status==="ready"?`<button class="btn s" onclick="completePickup('${pk.id}')">Pick up now</button>`:""}<button class="btn s" onclick="window.lastSaleId=null;render()" title="Hide this">✕</button></div></div></div>`; }
function newInvoice(){ showMargin=false; if(cur&&cur.editingId){ toast("Edit cancelled — invoice unchanged"); } const st=storeSettings(); const dt=defaultTax(); return {id:uid(),number:"",date:todayISO(),customerId:"",salesId:role()==="sales"?session.staffId:(session.staffId||""),lines:[],groups:[],discount:0,deliveryFee:0,taxRate:dt.rate,taxId:dt.id,taxName:dt.name,taxExempt:false,payments:[],status:"draft",notes:"",delivery:false,fulfillment:"",pickupDate:"",terms:"now"}; }
function addPlan(){ const pr=planRules(); const base=planBase(cur); if(base<=0) return toast("Add the merchandise first — the plan is priced from it.",true); if(cur.lines.some(l=>l.plan)) return toast("A protection plan is already on this sale.",true); const l=svcLine(pr.name,planPrice(base),{plan:true,planAuto:true,planAutoCost:true,cost:0}); if(cur.fundingId){ l.fundingId=cur.fundingId; } cur.lines.push(l); render(); toast(`${pr.name} at ${money(l.price)} (${pr.pct}% of ${money(base)}, min ${money(pr.min)}, max ${money(pr.max)}) — edit the price if needed`); }
function svcLine(name,price,extra){ return Object.assign({lineId:uid(),sku:"SVC",name,qty:1,price:round2(price),cost:0,pieces:0,service:true},extra||{}); }
function renderPOS(){
  if(!cur) cur=newInvoice(); const T=invTotals(cur); const st=storeSettings(); const lowM=st.lowMargin/100; const groups=cur.groups||[]; const c=byId("customers",cur.customerId);
  const lineHTML=(l,i)=>`<div class="line ${l.groupId?"in-group":""}"><input type="checkbox" ${selLines.has(i)?"checked":""} onchange="this.checked?selLines.add(${i}):selLines.delete(${i});render()"><div><div>${esc(l.name)}${l.special?` <span class="tag warn" title="Not in stock — will be ordered from the supplier for this customer">order from supplier${l.expected?" · est. "+dateShort(l.expected):""}</span>`:""}${l.plan?` <span class="tag info">${l.planAuto?"auto "+planRules().pct+"%":"custom price"}</span>`:""}${l.appFee?` <span class="tag info" title="Collected from the customer here; the company deducts it from your funding. Not taxed, no margin, no commission.">app fee · collected here</span>`:""}${l.promo?` <span class="tag warn" title="${esc(l.promo)}">sale · was ${money(l.listPrice)}</span>`:""}${l.trial?` <span class="tag ok">${st.trialNights}-night trial</span>`:""}</div><div class="muted meta"><span>${esc(l.sku)}${l.size?" · "+esc(l.size):""}</span>${showMargin?`<span>${seesCost()?"cost "+money(l.cost)+" ":""}<span class="${l.price&&(l.price-l.cost)/l.price<lowM?"tag bad":"tag ok"}">${pct(l.price?(l.price-l.cost)/l.price:0)} margin</span></span>`:""}${!l.service&&l.productId?(l.special?`${vendorStockButton(byId("products",l.productId),i)?vendorStockButton(byId("products",l.productId),i)+" · ":""}<a href="#" class="small" onclick="takesAnyway(${i});return false" title="The customer is taking this piece now (floor model or the count is wrong) — it comes out of stock even if the count says zero">customer takes it now</a> · <a href="#" class="small" onclick="toggleSpecial(${i});return false" title="Sell from stock instead, to be picked up / delivered later">change to in stock</a>`:`<span class="tag ok" title="Comes out of stock">in stock</span> <a href="#" class="small" onclick="toggleSpecial(${i});return false" title="Order this from the supplier for the customer instead">order instead</a>`):""}${fundingSources().length&&!l.appFee&&!l.surcharge&&(cur.fundingId||cur.lines.some(x=>x.fundingId))?(()=>{const sid=lineFundingId(cur,l);const s=sid?sourceById(cur,sid):null;return `<span class="ltog ${s?"on":""}" style="${s?"background:var(--blue2);border-color:var(--blue);color:var(--blue)":""}" onclick="assignFunding(${i})" title="Who pays for this item">${s?(s.type==="lease"?"Leased · ":"Financed · ")+esc(shortName(s)):"Customer pays"}</span>`})():""}${!l.service&&cur.fulfillment==="mixed"?`<select class="ltog" style="padding:2px 6px;height:auto;width:auto;font-size:12px" onchange="setLineFulfil(${i},this.value)" title="How this item reaches the customer"><option value="now" ${lineFulfil(cur,l)==="now"?"selected":""}>Takes now</option><option value="pickup" ${lineFulfil(cur,l)==="pickup"?"selected":""}>Pick up later</option><option value="delivery" ${lineFulfil(cur,l)==="delivery"?"selected":""}>Deliver</option></select>`:""}${!l.service&&(l.floorSample||(byId("products",l.productId)&&(byId("products",l.productId).floorSample||floorStock(byId("products",l.productId))>0)))?`<span class="ltog ${l.floorSample?"on":""}" onclick="toggleLineFlag(${i},'floorSample')" title="Sold as the floor model">Floor sample</span>`:""}${!l.service?`<span class="ltog ${l.asIs?"on asis":""}" onclick="toggleLineFlag(${i},'asIs')" title="Sold as-is: all sales final, no warranty">As-is</span>`:""}</div></div><input type="number" min="1" value="${l.qty}" onchange="setQty(${i},this.value)"><input type="number" step="0.01" value="${l.price}" onchange="setPrice(${i},this.value)" ${has("editPrice")||l.plan?"":"readonly style=\"background:var(--sage2)\" title=\"Price changes need a manager\""} ${l.groupId?'title="Shown to the customer as part of the package"':""}><div style="text-align:right;${l.groupId?"color:var(--ink2)":""}">${l.groupId?"in pkg":money(l.price*l.qty)}</div><button class="btn s" onclick="cur.lines.splice(${i},1);selLines.clear();render()">✕</button></div>`;
  const ungrouped=cur.lines.map((l,i)=>[l,i]).filter(([l])=>!l.groupId);
  cur.lines.forEach(l=>{ if(l.plan&&l.planAuto){ const np=planPrice(planBase(cur)); if(np!==l.price){ l.price=np; } } if(l.plan) l.cost=0; });
  const hasMat=cur.lines.some(l=>l.mattress), hasProt=cur.lines.some(isProtector), hasBase=cur.lines.some(isBase), hasHaul=cur.lines.some(l=>l.haulAway), hasFurn=cur.lines.some(l=>l.productId&&!l.mattress&&!isProtector(l)&&!isPillow(l)&&!isBase(l)), hasPlan=cur.lines.some(l=>l.plan);
  const sug=[]; if(hasMat&&!hasProt) sug.push(`<button class="chip" onclick="addByCategory('Protectors')">Protector${st.protectorRequired?" (needed for trial)":""}</button>`); if(hasMat&&!hasBase) sug.push(`<button class="chip" onclick="addByCategory('Adjustable bases')">Adjustable base</button><button class="chip" onclick="addByCategory('Foundations')">Foundation</button>`); if(hasMat&&!cur.lines.some(isPillow)) sug.push(`<button class="chip" onclick="addByCategory('Pillows')">Pillows</button>`); if(hasMat&&!hasHaul) sug.push(`<button class="chip" onclick="addHaul()">Haul-away</button>`); if((hasFurn||hasMat)&&!hasPlan) sug.push(`<button class="chip" onclick="addPlan()">Protection plan ${money(planPrice(planBase(cur)))}</button>`);
  const collSug=collectionSuggestions(); const credit=c?.credit||0;
  return `<div class="topbar">${st.logo&&st.logoOnPos!==false?`<img class="poslogo" src="${st.logo}" alt="">`:""}<h1 class="hot" ondblclick="toggleMargin()" title="Double-click to open the margin viewer">${cur.editingId?"Editing invoice":cur.status==="quote"?"Quote":cur.number?"Invoice":"New sale"} ${cur.number?`<span style="font-weight:500;color:var(--ink2)">${esc(cur.number)}</span>`:""}</h1><button class="btn" onclick="openScanner(c=>{const p=S.products.find(x=>x.sku.toLowerCase()===c.toLowerCase());if(p)addLine(p.id);else toast('No item with SKU '+c,true)})">Scan</button><button class="btn" onclick="cur=null;selLines.clear();showMargin=false;render()">Clear</button></div>
  ${lastSaleCard()}
  <div class="inv"><div>
    <div class="card" style="margin-bottom:16px"><div class="grid g3">
      <div class="field"><label class="f">Customer${storeSettings().requireCustomer!==false?' <span style="color:var(--red)">*</span>':""}</label><div class="row"><select onchange="cur.customerId=this.value;applyCustomerTax(byId('customers',this.value));cur.deliveryFeeManual=false;render()">${opts(S.customers,cur.customerId,x=>x.name,x=>x.id,"Walk-in")}</select><button class="btn s fx" onclick="editCustomer('',true)">+ New</button></div>${c?.sleepNotes?`<div class="muted small" style="margin-top:4px">${esc(c.sleepNotes)}</div>`:""}</div>
      <div class="field"><label class="f">Salesperson</label><div class="row">${cur.splits&&cur.splits.length?`<div class="small" style="padding:8px 0"><b>${esc(splitLabel(cur))}</b></div>`:`<select onchange="cur.salesId=this.value;render()">${opts(S.staff.filter(s=>s.active!==false&&s.role!=="driver"),cur.salesId,x=>x.name,x=>x.id,"—")}</select>`}<button class="btn s fx" onclick="splitModal()" title="Split the deal between salespeople or with the house">${cur.splits&&cur.splits.length?"Edit split":"Split"}</button></div>${cur.lines.some(l=>l.takeNow)?`<div class="notice" style="margin-top:6px">${cur.lines.filter(l=>l.takeNow).length} item${cur.lines.filter(l=>l.takeNow).length===1?"":"s"} marked <b>Takes today</b> — released at the sale, the rest goes on the ${cur.delivery?"delivery":"pickup"}.</div>`:""}${(()=>{const cc=byId("customers",cur.customerId); return cc&&!cc.referral?referralInline(cc):"";})()}${cur.salesId&&cur.salesId!==session.staffId&&!session.support?`<div class="muted small" style="margin-top:4px">Signed in as ${esc(firstName(me().name))} — ${esc(firstName(staffName(cur.salesId)))} will confirm with their PIN when the sale completes.</div>`:""}</div>
      <div class="field"><label class="f">Date</label><input type="date" value="${cur.date}" onchange="cur.date=this.value"></div></div>
      <div class="field rel"><label class="f">Add item — type SKU, name or size; scan; or press Enter</label><input type="text" id="item_q" placeholder="Search inventory…" oninput="itemSearch(this.value)" onkeydown="itemKey(event)" autocomplete="off"><div id="item_res"></div></div>
      <div class="chips" style="align-items:center">${dd("Add a charge",[["Setup & assembly ("+money(st.setupFee)+")",`customLine('White-glove setup & assembly',${st.setupFee},0)`],["Haul-away ("+money(st.haulAwayFee)+")","addHaul()"],["Protection plan (auto-priced)","addPlan()"],["Special order deposit","customLine('Special order deposit',0,0)"],null,["Custom charge","customLine('',0,0)"]],"s")}<button class="btn s" onclick="pickPackage()">Add package</button>${sug.length?`<span class="muted small" style="margin-left:6px">Suggested:</span>${sug.join("")}`:""}</div>${collSug.length?`<div class="chips" style="margin-top:8px;align-items:center"><span class="muted small">Goes with this${[...new Set(collSug.map(p=>p.collection).filter(Boolean))].length?" ("+[...new Set(collSug.map(p=>p.collection).filter(Boolean))].map(esc).join(", ")+")":""}:</span>${collSug.map(p=>`<button class="chip" onclick="addLine('${p.id}')" title="${esc(p.sku)}">${esc(p.name)} · ${money(effectivePrice(p))}</button>`).join("")}</div>`:""}
    </div>
    <div class="card">
      <div class="row" style="margin-bottom:8px"><h2>Items</h2><span class="fx muted">${selLines.size?`${selLines.size} selected`:"Tick items to bundle them into one package price"}</span><span class="fx bgroup"><button class="btn s p" onclick="makeGroup()" ${selLines.size?"":"disabled"}>Group as package</button>${selLines.size&&(cur.groups||[]).length?dd("Add to",(cur.groups||[]).map(g=>[esc(g.name),`addToGroup('${g.id}')`]),"s"):""}</span></div>
      ${!cur.lines.length?`<div class="empty">No items yet. Search above or scan a tag.</div>`:""}
      ${ungrouped.map(([l,i])=>lineHTML(l,i)).join("")}
      ${groups.map(g=>{const gl=cur.lines.map((l,i)=>[l,i]).filter(([l])=>l.groupId===g.id);const gcost=gl.reduce((a,[l])=>a+l.cost*l.qty,0),glist=gl.reduce((a,[l])=>a+l.price*l.qty,0);return `<div class="grp"><span><input type="text" value="${esc(g.name)}" onchange="gEdit('${g.id}','name',this.value)" style="width:190px;padding:3px 6px;font-weight:700"> <span class="muted" style="font-weight:500">${gl.length} items · list ${money(glist)}${g.price<glist?` · customer saves ${money(glist-g.price)}`:""}${showMargin?` · ${seesCost()?"cost "+money(gcost)+" · ":""}<b class="${g.price&&(g.price-gcost)/g.price<lowM?"tag bad":"tag ok"}">${pct(g.price?(g.price-gcost)/g.price:0)} margin</b>`:""}</span></span><span class="row fx"><span class="muted" style="font-weight:500">Package price</span><input type="number" step="1" value="${g.price}" onchange="gEdit('${g.id}','price',+this.value||0)" style="width:110px;padding:4px 8px;font-weight:700"><button class="btn s" onclick="ungroup('${g.id}')">Ungroup</button></span></div>${gl.map(([l,i])=>lineHTML(l,i)).join("")}`}).join("")}
    </div>
  </div>
  <div class="side"><div class="card">
    <div class="sec"><h4><span class="n">1</span>Customer gets it by</h4>
    ${cur.fulfillment==="mixed"?(()=>{ const k=fulfilCounts(cur); return `<div class="notice" style="margin:0"><b>Per item</b> — ${k.now} now · ${k.pickup} pickup · ${k.delivery} delivery. Set each item in the list below. <a href="#" onclick="setFulfillment('');return false">Back to one choice</a></div>`; })():`<div class="chips" style="gap:6px">${[["now","Takes it now"],["pickup","Pick up later"],["delivery","Delivery"]].map(([v,l])=>`<button class="chip ${cur.fulfillment===v?"on":""}" style="flex:1;justify-content:center;font-size:15px;padding:10px 8px;${!cur.fulfillment?"border-color:var(--amber)":""}" onclick="setFulfillment('${v}')">${l}</button>`).join("")}</div><div class="muted small" style="margin-top:6px">Partial pickups or deliveries are handled when they happen — nothing to decide now. <a href="#" onclick="setFulfillment('mixed');return false">Some items different?</a></div>`}
    </div>
    <div class="sec"><h4><span class="n">2</span>Totals</h4>
    <div class="tot"><span>Subtotal</span><b>${money(T.sub)}</b></div>
    <div class="tot"><span>Discount <a href="#" onclick="discountPct();return false" class="small">set %</a></span><input type="number" step="0.01" value="${cur.discount}" onchange="setDiscount(+this.value||0)" style="width:110px;padding:4px 8px;text-align:right"></div>
    ${cur.delivery?(()=>{const q=deliveryQuote(c,T.sub); if(cur.deliveryOption===undefined||cur.deliveryOption===null){ const di=q.options.findIndex(o=>o.id===(cur.deliveryOptionId||defaultDeliveryOption().id)); cur.deliveryOption=di>=0?di:0; } const o0=q.options[cur.deliveryOption]||q.options[0]; if(o0) cur.deliveryOptionId=o0.id; if(!cur.deliveryFeeManual){ if(o0&&cur.deliveryFee!==o0.fee) cur.deliveryFee=o0.fee; } return `<div class="tot"><span class="muted">Method</span><select style="width:215px;padding:4px 8px" onchange="setDeliveryOption(+this.value)">${q.options.map((o,i)=>`<option value="${i}" ${(cur.deliveryOption||0)===i?"selected":""}>${esc(o.name)} — ${money(o.fee)}</option>`).join("")}</select></div>${o0&&o0.carrier?`<div class="tot"><span class="muted">Tracking # (optional)</span><input type="text" value="${esc(cur.tracking||"")}" onchange="cur.tracking=this.value" style="width:215px;padding:4px 8px" placeholder="add when shipped"></div>`:""}<div class="muted small" style="text-align:right">${q.mi===null?"add a map pin to price by distance · ":q.mi.toFixed(0)+" mi · "}${q.distLabel} · ${q.orderLabel}${cur.deliveryFeeManual?" · <a href=\"#\" onclick=\"cur.deliveryFeeManual=false;render();return false\">use quoted fee</a>":""}</div>${cur.fundingId||cur.lines.some(x=>x.fundingId)?`<div class="tot"><span class="muted">Delivery paid by</span><select style="width:215px;padding:4px 8px" onchange="cur.deliveryFundingId=this.value;render()"><option value="" ${!cur.deliveryFundingId?"selected":""}>Customer</option>${[...new Set(cur.lines.map(l=>lineFundingId(cur,l)).filter(Boolean).concat(cur.fundingId?[cur.fundingId]:[]))].map(id=>{const s=sourceById(cur,id);return s?`<option value="${id}" ${cur.deliveryFundingId===id?"selected":""}>${esc(s.name)}</option>`:""}).join("")}</select></div>`:""}<div class="tot"><span class="muted">Delivery fee</span><input type="number" step="0.01" value="${cur.deliveryFee}" onchange="cur.deliveryFee=+this.value||0;cur.deliveryFeeManual=true;render()" style="width:110px;padding:4px 8px;text-align:right"></div>`})():""}
    <div class="taxrow"><span>Tax${(T.fundings||[]).some(f=>!f.upfront)?' <span class="muted small" style="white-space:nowrap">(leased items excluded)</span>':""}</span><span class="row" style="justify-content:flex-end;flex-wrap:nowrap;gap:6px"><select onchange="setTax(this.value)">${taxBrackets().map(t=>`<option value="${t.id}" ${!cur.taxExempt&&(cur.taxId||defaultTax().id)===t.id&&!cur.taxCustom?"selected":""}>${esc(t.name)} ${t.rate}%</option>`).join("")}${cur.taxCustom?`<option value="custom" selected>Custom ${cur.taxRate}%</option>`:""}<option value="exempt" ${cur.taxExempt?"selected":""}>Tax exempt</option></select><span style="min-width:70px;text-align:right">${money(T.tax)}</span></span></div>
    <div class="tot grand"><span>Total</span><span>${money(T.total)}</span></div>
    </div>
    ${showMargin?(seesCost()?`<div class="margin-box">${T.finFee?`<div class="r"><span>Margin before finance / lease fees</span><span>${pct(T.merch?(T.merch-T.cost)/T.merch:0)}</span></div><div class="r"><span>Finance / lease fees (${(T.fundings||[]).map(f=>esc(f.src.name)+" "+(f.src.feePct||0)+"%").concat(cur.financing?[esc(cur.financing.lender)+" "+(cur.financing.feePct||0)+"%"]:[]).join(", ")})</span><span>− ${money(T.finFee)}</span></div>`:""}<div class="r"><span>${T.finFee?"Margin after finance / lease fees":"Gross margin"}</span><span class="big ${T.marginPct<lowM?"low":""}">${pct(T.marginPct)}</span></div><div class="r"><span>Merchandise after discount</span><span>${money(T.merch)}</span></div>${T.planRev?`<div class="r"><span>Protection plan — not in cost of goods or margin</span><span>${money(T.planRev)}</span></div>`:""}${T.svcRev?`<div class="r"><span>Services — setup, haul-away, other (no margin calc)</span><span>${money(T.svcRev)}</span></div>`:""}<div class="r"><span>Cost of goods (landed)</span><span>${money(T.cost)}</span></div><div class="r"><span>Gross profit${T.finFee?" after fees":""}</span><span>${money(T.margin)}</span></div><div class="r" style="margin-top:6px;border-top:1px solid rgba(255,255,255,.15);padding-top:6px"><span>Est. commission (${esc(staffName(cur.salesId))})</span><span>${money(commissionFor(cur))}</span></div><div style="opacity:.7;margin-top:4px">Lowest price at ${st.lowMargin}% margin: ${money(T.cost/(1-lowM)+T.finFee)}</div></div>`:`<div class="margin-box"><div class="r"><span>Margin on this sale</span><span class="big ${T.marginPct<lowM?"low":""}">${pct(T.marginPct)}</span></div><div class="r"><span>Store target</span><span>${st.lowMargin}%+</span></div>${staffLimit("minMarginPct",0)?`<div class="r"><span>Your floor</span><span>${staffLimit("minMarginPct",0)}%</span></div>`:""}<div class="r" style="margin-top:6px;border-top:1px solid rgba(255,255,255,.15);padding-top:6px"><span>Est. commission (${esc(staffName(cur.salesId))})</span><span>${money(commissionFor(cur))}</span></div><div style="opacity:.7;margin-top:4px">${T.marginPct<lowM?"Below target — a manager may need to approve.":"Healthy margin."}</div></div>`):""}
    <div class="sec"><h4><span class="n">3</span>Payment</h4>
    <div class="field" style="margin-top:0"><label class="f">Payment terms</label><div class="chips"><button class="chip ${cur.terms==="now"?"on":""}" onclick="setTerms('now');delete cur.financing;delete cur.layaway;render()">Pay now</button><button class="chip ${cur.terms==="financing"?"on":""}" onclick="setTerms('financing');financingModal()">Financing</button><button class="chip ${cur.terms==="lease"?"on":""}" onclick="setTerms('lease')">Lease-to-own</button><button class="chip ${cur.terms==="layaway"?"on":""}" onclick="setTerms('layaway');layawayModal()">Layaway</button></div>${cur.terms==="lease"||cur.terms==="financing"?`<div class="field" style="margin-top:8px"><label class="f">${cur.terms==="lease"?"Lease-to-own company":"Financing company"}</label><select onchange="chooseFunding(this.value)">${opts(fundingSources().filter(s=>s.type===(cur.terms==="lease"?"lease":"finance")),cur.fundingId,x=>x.name+(x.taxUpfront===false?" (no tax up front)":""),x=>x.id,"Choose…")}</select></div>${fundingSummary(T,cur)}`:""}
    ${cur.financing?`<div class="muted small" style="margin-top:6px">${esc(cur.financing.lender)} · ${cur.financing.months} mo at ${cur.financing.apr}% APR · ${money(cur.financing.monthly)}/mo · down ${money(cur.financing.down)}</div>`:""}
    ${cur.layaway?`<div class="muted small" style="margin-top:6px">Deposit ${money(cur.layaway.deposit)} today · ${cur.layaway.schedule.length} payments of ${money(cur.layaway.schedule[0]?.amount||0)} · final ${dateShort(cur.layaway.schedule.slice(-1)[0]?.due||"")}</div>`:""}</div>
    <div class="field"><label class="f">Payment ${cur.terms==="layaway"?"(deposit)":cur.terms==="financing"?"(down payment)":"now"}</label><div class="row"><select id="pay_method" onchange="const h=document.getElementById('pay_hint');if(h)h.style.display=this.value==='Card'?'':'none'">${(T.fundings||[]).map(f=>`<option value="${esc((f.src.type==="lease"?"Lease — ":"Financing — ")+f.src.name)}" data-fid="${f.src.id}">${esc(f.src.name)} pays ${money(Math.max(0,f.amount-fundedPaid(cur,f.src)))}</option>`).join("")}${tenderTypes().map(m=>`<option>${esc(m)}</option>`).join("")}${credit>0?`<option value="Store credit">Store credit (${money(credit)} available)</option>`:""}</select><input type="number" step="0.01" id="pay_amt" placeholder="${(cur.terms==="layaway"?(cur.layaway?.deposit||0):(cur.terms==="financing"&&!cur.fundingId)?(cur.financing?.down||0):(T.balance||0)).toFixed(2)}"><button class="btn fx" onclick="addPayment()">Add</button></div><div id="pay_hint" class="muted small" style="margin-top:4px">Card payments open the card panel when you press Add.</div></div>
    ${cur.payments.length||T.total>0?`<div class="pays">${cur.payments.map((p,i)=>`<div class="p"><span class="m">${esc(p.method)}${p.last4?" ····"+esc(p.last4):""}${p.date&&p.date!==cur.date?` <span class="muted small">${dateShort(p.date)}</span>`:""}</span><span>${money(p.amount)}</span><a href="#" class="x" title="Remove this payment" onclick="cur.payments.splice(${i},1);render();return false">✕</a></div>`).join("")}${cur.payments.length?`<div class="p" style="background:var(--surface2,#fafafa)"><span class="m muted">Received</span><span>${money(T.paid)}</span><span style="width:24px"></span></div>`:""}<div class="bal ${T.balance<=0.005?"zero":"due"}"><span>${T.balance<=0.005?"Paid in full":"Balance due"}</span><span>${money(Math.max(0,T.balance))}</span></div></div>`:""}
    </div>
    <details style="margin-top:12px"${cur.notes?" open":""}><summary class="small" style="cursor:pointer;color:var(--ink2)">Notes on invoice${cur.notes?" ✓":""}</summary><textarea rows="2" style="margin-top:6px" onchange="cur.notes=this.value">${esc(cur.notes)}</textarea></details>
    ${(!cur.fulfillment||(storeSettings().requireCustomer!==false&&!cur.customerId))&&cur.lines.length?`<div class="muted small" style="margin-bottom:6px">Required before completing: ${[!cur.customerId&&storeSettings().requireCustomer!==false?"customer (name, phone, address)":"",!cur.fulfillment?"fulfillment":""].filter(Boolean).join(" · ")}</div>`:""}${has("complete")?`<button class="btn p w" onclick="finalizeInvoice()" ${cur.lines.length?"":"disabled"}>Complete sale</button>`:`<div class="notice small" style="margin:0">Your login builds the sale — save it as a quote and a cashier or manager will complete it.</div>`}
    <div class="row" style="margin-top:8px"><button class="btn" onclick="printInvoice(cur)">Preview</button>${has("quote")?`<button class="btn" onclick="saveQuote()" ${cur.lines.length?"":"disabled"}>Save quote</button>`:""}</div>
  </div></div></div>`;
}
function afterPOS(){ const el=document.getElementById("item_q"); if(el&&!cur.lines.length&&window.innerWidth>920) el.focus(); }
document.addEventListener("keydown",e=>{ if(session&&view==="pos"&&(e.key==="m"||e.key==="M")&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){ toggleMargin(); } });
let itemHits=[], itemHl=0;
function itemSearch(q){ q=q.toLowerCase().trim(); const r=document.getElementById("item_res"); if(!q){r.innerHTML="";itemHits=[];return} itemHits=S.products.filter(p=>[p.sku,p.name,p.category,p.size,p.comfort,p.family].join(" ").toLowerCase().includes(q)).slice(0,9); itemHl=0; r.innerHTML=itemHits.length?`<div class="search-res">${itemHits.map((p,i)=>`<div class="${i===0?"hl":""}" onmousedown="addLine('${p.id}')"><span><b>${esc(p.sku)}</b> ${esc(p.name)}${isMattress(p)?` <span class="muted">${esc(p.size)} · ${esc(p.comfort)}</span>`:""} ${p.floorSample?'<span class="tag info">floor</span>':""} <span class="tag ${(p.stock||0)>0?"ok":"warn"}">${(p.stock||0)>0?"stock "+p.stock:"order"}</span></span><span>${money(p.price)}</span></div>`).join("")}</div>`:`<div class="search-res"><div class="muted">No match — <a href="#" onmousedown="editProduct()">add a new item</a></div></div>`; }
function itemKey(e){ if(e.key==="ArrowDown"||e.key==="ArrowUp"){ e.preventDefault(); if(!itemHits.length) return; itemHl=(itemHl+(e.key==="ArrowDown"?1:-1)+itemHits.length)%itemHits.length; document.querySelectorAll("#item_res .search-res div").forEach((d,i)=>d.classList.toggle("hl",i===itemHl)); } else if(e.key==="Enter"){ const q=e.target.value.trim(); const exact=S.products.find(p=>p.sku.toLowerCase()===q.toLowerCase()); if(exact) addLine(exact.id); else if(itemHits[itemHl]) addLine(itemHits[itemHl].id); } else if(e.key==="Escape"){ document.getElementById("item_res").innerHTML=""; } }
function makeLine(p,qty){ qty=qty||1; const promo=promoFor(p); const l={lineId:uid(),productId:p.id,sku:p.sku,name:p.name,category:p.category,subcategory:p.subcategory||"",collection:p.collection||"",model:p.model||"",qty,price:effectivePrice(p),listPrice:promo?p.price:undefined,promo:promo?promo.name:undefined,cost:landedCost(p),bin:p.bin,pieces:p.isKit?(kitPieces(p)||1):(p.pieces||1),warrantyYears:p.warrantyYears||0,mattress:isMattress(p),size:p.size||"",trial:isMattress(p)&&p.trial!==false,floorSample:!!p.floorSample}; if(p.isKit) l.kit=(p.kitItems||[]).map(k=>({productId:k.productId,qty:k.qty})); const avail=p.isKit?kitStock(p):deliverableStock(p); if(!p.floorSample&&avail<qty){ l.special=true; l.specialStatus="pending"; l.expected=addDays(todayISO(),byId("vendors",p.vendorId)?.leadDays||21); if(!p.isKit&&floorStock(p)>0) setTimeout(()=>toast(`${p.name}: only the floor model is in stock — mark the line Floor sample to sell it, or it will be ordered.`),50); } return l; }
function addLine(pid,qty){ const p=byId("products",pid); if(!p) return; qty=qty||1; const ex=cur.lines.find(l=>l.productId===pid&&!l.groupId); if(ex){ ex.qty+=qty; } else { const nl=makeLine(p,qty); if(p.asIs){ nl.asIs=true; nl.asIsNote=p.asIsNote||""; nl.floorSample=true; } cur.lines.push(nl); } render(); const el=document.getElementById("item_q"); if(el){el.value="";const r=document.getElementById("item_res"); if(r) r.innerHTML="";el.focus()} }
function addByCategory(cat){ const list=S.products.filter(p=>(p.subcategory===cat||p.category===cat)&&effStock(p)>0); const mat=cur.lines.find(l=>l.mattress); const sized=mat?list.filter(p=>!p.size||p.size===mat.size||(mat.size==="Split King"&&p.size==="Twin XL")):list; const pick=(sized.length?sized:list); if(!pick.length){ toast(`No ${cat.toLowerCase()} in stock — add them in Inventory.`,true); return; } if(pick.length===1) return addLine(pick[0].id); modal(`<h2>${esc(cat)}</h2>${table(pick,[["Item",p=>`${esc(p.name)}${p.size?` <span class="muted">${esc(p.size)}</span>`:""}`],["Price",p=>money(p.price),"n"],["",p=>`<button class="btn s p" onclick="closeModal();addLine('${p.id}')">Add</button>`]],"")}<div class="actions"><button class="btn" onclick="closeModal()">Cancel</button></div>`); }
function addHaul(){ const st=storeSettings(); cur.lines.push(svcLine(cur.lines.some(l=>l.mattress)?"Old mattress haul-away":"Old furniture haul-away",st.haulAwayFee,{haulAway:true})); render(); }
function addCustomLine(){ const price=fnum("cl_price"); const name=fv("cl_name")||"Charge"; const add=()=>{ cur.lines.push(svcLine(name,price,Object.assign({cost:fnum("cl_cost")},window._clExtra||{}))); closeModal(); render(); }; if(price<0){ const T=invTotals(cur); const pct=T.sub?Math.abs(price)/T.sub*100:100; const lim=staffLimit("discount"); if(!has("discount")||(lim!==null&&pct>lim+0.001)){ return managerOverride(`A negative charge (${money(price)}) is a discount of ${pct.toFixed(1)}% — over this login's limit.`,()=>{ logAudit("negative_line",`${name} ${money(price)}`,{amount:price}); add(); }); } logAudit("negative_line",`${name} ${money(price)}`,{amount:price}); } add(); }
function customLine(name,price,cost,extra){ modal(`<h2>Add charge</h2><div class="field"><label class="f">Description</label><input type="text" id="cl_name" value="${esc(name)}"></div><div class="grid g2"><div class="field"><label class="f">Price</label><input type="number" step="0.01" id="cl_price" value="${price||""}"></div><div class="field"><label class="f">Our cost (for margin)</label><input type="number" step="0.01" id="cl_cost" value="${cost||0}"></div></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="addCustomLine()">Add</button></div>`); window._clExtra=extra||{}; }
function setQty(i,v){ const l=cur.lines[i]; l.qty=Math.max(1,+v||1); const p=byId("products",l.productId); if(p&&!l.service&&!p.floorSample){ if((p.stock||0)<l.qty&&!l.special){ l.special=true; l.specialStatus="pending"; l.expected=addDays(todayISO(),byId("vendors",p.vendorId)?.leadDays||21); toast("Quantity exceeds stock — marked as special order"); } } render(); }
function setPrice(i,v){ const l=cur.lines[i]; const np=+v||0; if(!l.plan&&!l.service){ const p=byId("products",l.productId); const list=l.listPrice||(p?p.price:l.price); if(np<list-0.005) logAudit("price",`${l.name}: ${money(list)} → ${money(np)}`,{amount:np-list}); } if(l.plan){ l.price=np; l.planAuto=false; l.cost=0; render(); return; } const p=byId("products",l.productId); const st=storeSettings(); if(!has("editPrice")){ managerOverride("Changing prices needs a manager.",()=>{l.price=np;render()}); render(); return; } if(p&&p.map&&np<+p.map){ toast(`${p.name} can't be sold below the vendor MAP of ${money(p.map)}.`,true); render(); return; } const lim=staffLimit("maxDiscountPct",st.discountLimitPct); if(p&&np<p.price*(1-lim/100)&&!has("approve")){ managerOverride(`Price below ${lim}% off list (${money(p.price)}) needs manager approval.`,()=>{l.price=np;render()}); render(); return; } l.price=np; render(); }
function toggleLineFlag(i,flag){ const l=cur.lines[i]; l[flag]=!l[flag]; const st=storeSettings(); if(flag==="floorSample"&&l.floorSample&&!l.fsMarkdownOffered&&st.floorSampleMarkdown){ l.fsMarkdownOffered=true; const p=byId("products",l.productId); const base=l.listPrice||(p?p.price:l.price); const md=applyRounding(base*(1-st.floorSampleMarkdown/100),Object.assign({},costRules(),{rounding:"down"})); if(md<l.price&&(has("discount")&&(staffLimit("discount")===null||st.floorSampleMarkdown<=staffLimit("discount"))||has("approve"))&&confirm(`Apply the ${st.floorSampleMarkdown}% floor-sample markdown? ${money(l.price)} → ${money(md)}`)){ if(p&&p.map&&md<+p.map) toast(`Kept at the vendor MAP of ${money(p.map)}`); l.price=p&&p.map?Math.max(md,+p.map):md; } } if(flag==="asIs"&&l.asIs) toast("Marked as-is: no returns, no warranty — prints on the invoice with an acknowledgment line"); render(); }
function takesAnyway(i){ const l=cur.lines[i]; const p=byId("products",l.productId); logAudit("takes_now",`${l.name} ×${l.qty} taken with stock at ${p?deliverableStock(p):"?"}`); delete l.special; delete l.specialStatus; delete l.expected; l.takeNow=true; render(); const left=p?deliverableStock(p)-l.qty:0; toast(`${l.name} marked as taken by the customer now${p&&left<0?" — stock will show "+left+"; fix the count under Inventory if it is wrong":""}.`); }
function toggleSpecial(i){ const l=cur.lines[i]; if(l.special){ const p=byId("products",l.productId); if(p&&!p.isKit&&deliverableStock(p)<l.qty&&!confirm(`${p.name} has ${deliverableStock(p)} deliverable in stock. Selling it as in-stock will take stock negative and it won't be linked to a purchase order for this customer. Continue?`)) return; delete l.special; delete l.specialStatus; delete l.expected; } else { l.special=true; l.specialStatus="pending"; l.expected=addDays(todayISO(),byId("vendors",byId("products",l.productId)?.vendorId)?.leadDays||21); } render(); }
function setTax(v){ if(v==="exempt"){ cur.taxExempt=true; } else if(v==="custom"){ cur.taxExempt=false; } else { const t=taxById(v); if(t){ cur.taxExempt=false; cur.taxCustom=false; cur.taxId=t.id; cur.taxName=t.name; cur.taxRate=t.rate; } } render(); }
function applyCustomerTax(c){ cur.taxCustom=false; if(c&&c.taxExempt){ cur.taxExempt=true; return; } cur.taxExempt=false; if(c&&c.taxRate){ cur.taxCustom=true; cur.taxRate=c.taxRate; cur.taxName="Custom"; cur.taxId=""; return; } const t=(c&&c.taxBracketId&&taxById(c.taxBracketId))||defaultTax(); cur.taxId=t.id; cur.taxName=t.name; cur.taxRate=t.rate; }
function setFulfillment(v){ const prev=cur.fulfillment; cur.fulfillment=v; if(v==="mixed"){ cur.lines.forEach(l=>{ if(l.service) return; if(!l.fulfil) l.fulfil=l.takeNow?"now":prev==="delivery"?"delivery":prev==="now"?"now":"pickup"; delete l.takeNow; }); } else { cur.lines.forEach(l=>{ delete l.fulfil; }); } syncDeliveryFlag(); render(); }
function syncDeliveryFlag(){ const wasDel=!!cur.delivery; cur.delivery=cur.fulfillment==="delivery"||(cur.fulfillment==="mixed"&&cur.lines.some(l=>!l.service&&l.fulfil==="delivery")); if(!cur.delivery){ cur.deliveryFee=0; cur.deliveryFundingId=""; } else if(!wasDel){ cur.deliveryFeeManual=false; } }
function setLineFulfil(i,v){ const l=cur.lines[i]; l.fulfil=v; if(v==="now"&&l.special){ l.fulfil="pickup"; toast("That item isn't in stock — it will be held for pickup when it arrives.",true); } syncDeliveryFlag(); render(); }
function setDeliveryOption(i){ cur.deliveryOption=i; const o=deliveryOptions()[i]; cur.deliveryOptionId=o?o.id:""; cur.deliveryFeeManual=false; render(); }
function setDiscount(v){ const st=storeSettings(); const T=invTotals(Object.assign({},cur,{discount:0})); const lim=has("discount")?staffLimit("maxDiscountPct",st.discountLimitPct):0; if(T.sub&&v>0&&v/T.sub*100>lim&&!has("approve")){ managerOverride(lim?`Discount over ${lim}% needs manager approval.`:"This user can't give discounts without a manager.",()=>{cur.discount=v;render()}); render(); return; } cur.discount=round2(v); render(); }
function discountPct(){ modal(`<h2>Discount</h2><div class="field"><label class="f">Percent off subtotal</label><input type="number" id="dp" value="10"></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="const s=invTotals(Object.assign({},cur,{discount:0})).sub;closeModal();setDiscount(round2(s*fnum('dp')/100))">Apply</button></div>`); }
function toggleMargin(){ if(showMargin){showMargin=false;render();return} if(has("margin")){showMargin=true;render();return} managerOverride("This user isn't allowed to see margins.",()=>{showMargin=true;render()}); }
function makeGroup(){ const ids=[...selLines].filter(i=>cur.lines[i]&&!cur.lines[i].groupId); if(!ids.length) return toast("Select ungrouped items first."); const list=ids.reduce((a,i)=>a+cur.lines[i].price*cur.lines[i].qty,0); const g={id:uid(),name:"Package "+((cur.groups||[]).length+1),price:Math.round(list)}; cur.groups=cur.groups||[]; cur.groups.push(g); ids.forEach(i=>cur.lines[i].groupId=g.id); selLines.clear(); render(); toast("Package created — set its price"); }
function gEdit(id,k,v){ const g=cur.groups.find(x=>x.id===id); if(k==="price"){ const gl=cur.lines.filter(l=>l.groupId===id); const list=gl.reduce((a,l)=>a+l.price*l.qty,0); const st=storeSettings(); const lim=staffLimit("maxDiscountPct",st.discountLimitPct); if(list&&(list-v)/list*100>lim&&!has("approve")){ managerOverride(`Package discount over ${lim}% needs manager approval.`,()=>{g.price=v;render()}); render(); return; } } g[k]=v; render(); }
function ungroup(id){ cur.lines.forEach(l=>{if(l.groupId===id) delete l.groupId}); cur.groups=cur.groups.filter(g=>g.id!==id); render(); }
function addPayment(){ const T=invTotals(cur); const method=fv("pay_method"); if(method==="Card"&&cardPanelOn()){ const fl=(T.fundings||[]).reduce((a,f)=>a+Math.max(0,f.amount-fundedPaid(cur,f.src)),0); const amt=fnum("pay_amt")||Math.max(0,round2(T.balance-fl)); window._cardTarget=null; return cardPanel(amt); } const sel=document.getElementById("pay_method"); const fid=sel&&sel.selectedOptions&&sel.selectedOptions[0]?sel.selectedOptions[0].dataset.fid:""; const fsrc=fid?(T.fundings||[]).find(f=>f.src.id===fid):(T.fundings||[]).find(f=>method==="Lease — "+f.src.name||method==="Financing — "+f.src.name); const fundedLeftAll=round2((T.fundings||[]).reduce((a,f)=>a+Math.max(0,f.amount-fundedPaid(cur,f.src)),0)); let amt=fnum("pay_amt")||(fsrc?round2(Math.max(0,fsrc.amount-fundedPaid(cur,fsrc.src))):cur.terms==="layaway"?cur.layaway?.deposit:cur.terms==="financing"&&!(T.fundings||[]).length?cur.financing?.down:Math.min(T.balance,(T.fundings||[]).length?round2(T.balance-fundedLeftAll):T.balance))||0; window._payFid=fsrc?fsrc.src.id:""; if(amt<=0) return; if(method==="Store credit"){ const c=byId("customers",cur.customerId); const avail=(c?.credit||0)-cur.payments.filter(p=>p.method==="Store credit").reduce((a,p)=>a+p.amount,0); if(amt>avail) amt=avail; if(amt<=0) return toast("No store credit left.",true); } if(amt>T.balance+0.005){ if(method==="Cash") toast(`Change due: ${money(amt-T.balance)}`); amt=T.balance; } cur.payments.push(Object.assign({method,amount:round2(amt),date:todayISO(),by:session.staffId},window._payFid?{fundingId:window._payFid}:{})); render(); }
function financeCompanies(){ return fundingSources().filter(s=>s.type==="finance"); }
function financingModal(){ const st=storeSettings(); const T=invTotals(cur); const cos=financeCompanies(); const f=cur.financing||{}; const lim=+st.financeManagerMonths||12;
  if(!cos.length) return toast("No financing companies set up yet — add them under Settings → Payments & financing.",true);
  const co=cos.find(c=>c.id===f.sourceId)||cos[0]; const plans=(co.plans&&co.plans.length)?co.plans:[{name:(co.months||12)+" months",months:co.months||12,feePct:co.feePct||0,apr:co.apr||0}];
  modal(`<h2>Financing</h2><p class="muted">Total ${money(T.total)}. The finance company pays the store; the customer pays them monthly. Fees and rates come from the plan — they aren't changed on a sale.</p><div class="grid g2"><div class="field"><label class="f">Company</label><select id="fn_co" onchange="cur.financing=Object.assign({},cur.financing||{},{sourceId:this.value,planIdx:0});financingModal()">${cos.map(c=>`<option value="${c.id}" ${c.id===co.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></div><div class="field"><label class="f">Plan</label><select id="fn_plan" onchange="fnPlanChanged()">${plans.map((p,i)=>`<option value="${i}" ${i===(f.planIdx||0)?"selected":""}>${esc(p.name||p.months+" months")} — ${p.months} mo${p.months>lim?" 🔒":""}</option>`).join("")}</select></div></div>
  <div class="grid g3"><div class="field"><label class="f">Merchant fee</label><input type="text" id="fn_fee_show" value="${plans[f.planIdx||0].feePct||0}%" disabled></div><div class="field"><label class="f">Customer APR</label><input type="text" id="fn_apr_show" value="${plans[f.planIdx||0].apr||0}%" disabled></div><div class="field"><label class="f">Down payment</label><input type="number" step="0.01" id="fn_down" value="${f.down||0}"></div></div><div class="muted small" id="fn_lock" style="${plans[f.planIdx||0].months>lim?"":"display:none"}">🔒 Terms longer than ${lim} months need a manager's PIN when you apply.</div>
  <div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="applyFinancing()">Apply</button></div>`); window._fnPlans=plans; window._fnCo=co; }
function fnPlanChanged(){ const i=+fv("fn_plan")||0; const p=window._fnPlans[i]; const lim=+storeSettings().financeManagerMonths||12; document.getElementById("fn_fee_show").value=(p.feePct||0)+"%"; document.getElementById("fn_apr_show").value=(p.apr||0)+"%"; const l=document.getElementById("fn_lock"); if(l) l.style.display=p.months>lim?"":"none"; }
function applyFinancing(){ const T=invTotals(cur); const i=+fv("fn_plan")||0; const p=window._fnPlans[i]; const co=window._fnCo; const lim=+storeSettings().financeManagerMonths||12; const down=Math.min(fnum("fn_down"),T.total); const go=(approver)=>{ const months=p.months, apr=p.apr||0; const P=T.total-down; const r=apr/100/12; const monthly=r>0?P*r/(1-Math.pow(1+r,-months)):P/months; cur.financing={lender:co.name+" — "+(p.name||months+" months"),sourceId:co.id,planIdx:i,planName:p.name||"",months,apr,down:round2(down),monthly:round2(monthly),feePct:p.feePct||0,amount:round2(P),approvedBy:approver||""}; cur.terms="financing"; delete cur.layaway; closeModal(); render(); if(approver) logAudit("override",`Financing term ${months} months on ${co.name} approved by manager`,{months}); };
  if(p.months>lim&&!isManager()) return managerOverride(`Financing over ${lim} months (${p.months} months on ${co.name}) needs a manager.`,(who)=>go(who&&who.id)); if(p.months>lim) logAudit("override",`Financing term ${p.months} months on ${co.name} (manager)`); go(); }
function layawayModal(){ const T=invTotals(cur); const l=cur.layaway||{deposit:round2(T.total*0.2),n:3,every:"month"};
  modal(`<h2>Layaway</h2><p class="muted">Items are reserved and delivered after the final payment. Total ${money(T.total)}.</p><div class="grid g3"><div class="field"><label class="f">Deposit today</label><input type="number" step="0.01" id="la_dep" value="${l.deposit}"></div><div class="field"><label class="f">Number of payments</label><input type="number" id="la_n" value="${l.n}"></div><div class="field"><label class="f">Every</label><select id="la_every"><option value="2weeks" ${l.every==="2weeks"?"selected":""}>2 weeks</option><option value="month" ${l.every==="month"?"selected":""}>Month</option></select></div></div>
  <div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="applyLayaway()">Apply</button></div>`); }
function applyLayaway(){ const T=invTotals(cur); const dep=Math.min(fnum("la_dep"),T.total), n=Math.max(1,Math.round(fnum("la_n"))), every=fv("la_every"); const rem=round2(T.total-dep); const each=round2(rem/n); const schedule=[]; for(let i=1;i<=n;i++){ schedule.push({due:addDays(todayISO(),every==="month"?30*i:14*i),amount:i===n?round2(rem-each*(n-1)):each,paid:false}); } cur.layaway={deposit:round2(dep),n,every,schedule}; cur.terms="layaway"; delete cur.financing; closeModal(); render(); }
async function saveQuote(){ const st=storeSettings(); if(!cur.number) cur.number=nextNumber("nextInvoice","Q"); cur.status="quote"; cur.quotedBy=session.staffId; cur.expires=addDays(todayISO(),st.quoteDays||30); await save("invoices",cur); if(cur.customerId) await addFollowup(cur.customerId,cur.id,"Quote follow-up",`Follow up on quote ${cur.number} (${money(invTotals(cur).total)}) — expires ${dateShort(cur.expires)}.`,addDays(todayISO(),2)); toast(`Quote saved — valid ${st.quoteDays||30} days`); cur=null; selLines.clear(); showMargin=false; go("invoices"); }
async function finalizeInvoice(force){
  if(!has("complete")) return denied("complete sales — save it as a quote and a cashier or manager will complete it");
  if(!cur.lines.length) return; const T=invTotals(cur); const st=storeSettings();
  if(!cur.fulfillment&&!cur.delivery) return toast("Choose the fulfillment: takes it today, hold for pickup, or delivery.",true);
  if(cardPanelOn()&&cardCfg().requireLast4!==false&&cur.payments.some(p=>p.method==="Card"&&!(p.card&&/^\d{4}$/.test(p.card.last4||"")))) return toast("Every card payment needs the last 4 digits of the card — remove the payment and re-enter it through the card panel.",true);
  const walkinMax=+st.walkinMax||0; const smallCashCarry=walkinMax>0&&cur.fulfillment==="now"&&!cur.delivery&&cur.terms==="now"&&T.total<=walkinMax; const needsCust=(st.requireCustomer!==false&&!smallCashCarry)||cur.delivery||cur.fulfillment==="pickup"||cur.terms!=="now"||cur.lines.some(l=>l.special)||cur.lines.some(l=>l.mattress&&l.trial);
  if(needsCust&&!cur.customerId) return toast("Add the customer (name, phone and address are required) before completing the sale.",true);
  if(cur.customerId){ const cc=byId("customers",cur.customerId); if(!cc?.referral&&st.askReferral==="required"){ render(); return toast("Choose how the customer heard about us (the dropdown under the customer).",true); } const needAddr=cur.delivery||st.requireAddress==="always"; const missing=[!cc?.name&&"name",!cc?.phone&&"phone number",(needAddr&&!cc?.address)&&"address (needed for delivery)"].filter(Boolean); if(missing.length&&st.requireCustomer!==false) return editCustomer(cur.customerId,true,`Please add the customer's ${missing.join(", ")} — required to complete the sale.`); }
  if(cur.terms==="financing"&&!cur.financing) return financingModal();
  if(cur.terms==="layaway"&&!cur.layaway) return layawayModal();
  if(cur.terms==="financing"){ const paidDown=T.paid; if(paidDown+0.005<cur.financing.down) return toast(`Collect the ${money(cur.financing.down)} down payment first (${money(paidDown)} taken).`,true); cur.payments.push({method:"Financing — "+cur.financing.lender,amount:round2(T.total-paidDown),date:todayISO(),by:session.staffId}); }
  if(cur.terms==="layaway"&&T.paid+0.005<cur.layaway.deposit) return toast(`Collect the ${money(cur.layaway.deposit)} deposit first.`,true);
  { const st2=storeSettings(); const mode=st2.pinOnSale||"different"; const sid=cur.salesId; if(mode!=="off"&&sid&&sid!==HOUSE_ID&&!session.support&&!cur.pinVerified&&(mode==="always"||sid!==session.staffId)){ return verifyPin(sid,`This sale is credited to ${staffName(sid)}${sid!==session.staffId?" while "+me().name+" is signed in":""}.`,()=>{cur.pinVerified=sid;return finalizeInvoice(force)}); } }
  { const pctD=+st.specialDepositPct||0; if(pctD>0&&cur.terms==="now"&&!force){ const ordered=cur.lines.filter(l=>l.special&&!l.takeNow); if(ordered.length){ const base=ordered.reduce((a,l)=>a+(+l.price||0)*(+l.qty||1),0); const need=round2(base*pctD/100); const custPaid=cur.payments.reduce((a,p)=>a+(+p.amount||0),0); if(custPaid+0.005<need){ if(has("approve")){ if(!confirm(`Supplier orders on this sale need a ${pctD}% deposit (${money(need)}); ${money(custPaid)} has been taken. Complete anyway?`)) return; cur.depositWaived={by:session.staffId,at:todayISO()}; } else return managerOverride(`Supplier orders need a ${pctD}% deposit (${money(need)}) before the sale can be completed — ${money(custPaid)} taken so far. Collect the deposit or ask a manager.`,()=>{ cur.depositWaived={by:session.staffId,at:todayISO()}; return finalizeInvoice(force); }); } } } }
  { const over=(T.fundings||[]).filter(f=>{ const lim=fundingLimit(cur,f.src); return lim!==null&&f.amount>lim+0.005; }); if(over.length) return toast(`${over.map(f=>f.src.name).join(", ")}: items assigned exceed the approved amount${over[0].src.bufferPct?" (incl. "+over[0].src.bufferPct+"% buffer)":""} — move an item to the customer or another company.`,true); }
  if(cur.terms==="now"&&T.balance>0.005&&!has("balance")&&!force){ return managerOverride(`Completing with a balance of ${money(T.balance)} needs manager approval.`,()=>finalizeInvoice(true)); }
  { const mm=staffLimit("minMarginPct",0); if(mm&&T.marginPct*100<mm&&!force&&!has("approve")) return managerOverride(`This sale is at ${pct(T.marginPct)} margin — below this user's floor of ${mm}%.`,()=>finalizeInvoice(true)); }
  if(cur.editingId){ const orig=byId("invoices",cur.editingId); if(orig){ for(const l of orig.lines){ if(l.kit&&!l.special){ for(const k of l.kit){ const cp=byId("products",k.productId); if(cp){ stockMove(cp,k.qty*l.qty,l.locationId); await save("products",cp); } } continue; } if(l.productId&&!l.special&&!l.service){ const p=byId("products",l.productId); if(p){ stockMove(p,l.qty,l.locationId); await save("products",p); } } } for(const d of S.deliveries.filter(d=>d.invoiceId===orig.id)){ if(["unscheduled","scheduled","awaiting","ready","partready","planned"].includes(d.status)||(d.kind==="pickup"&&d.status!=="pickedup")){ await remove("deliveries",d.id); } } cur.id=orig.id; cur.number=orig.number; cur.date=orig.date; cur.editedAt=todayISO(); cur.editedBy=session.staffId; logAudit("edit",`${orig.number}: items edited in the register (${orig.lines.length} → ${cur.lines.length} lines, total ${money(invTotals(orig).total)} → ${money(invTotals(cur).total)})`,{invoiceId:orig.id}); } delete cur.editingId; }
  if(cur.number.startsWith("Q")||!cur.number) cur.number=nextNumber("nextInvoice","INV");
  const T2=invTotals(cur);
  cur.status=cur.terms==="layaway"?"layaway":(cur.terms==="financing"||cur.terms==="lease")?"financed":T2.balance<=0.005?"paid":"open"; cur.completedAt=Date.now(); cur.completedBy=session.staffId; cur.rungBy=session.staffId; if(cur.pinVerified) cur.verifiedBy=cur.pinVerified; { const T0=invTotals(cur); const bits=[]; if(T0.disc) bits.push("discount "+money(T0.disc)); if(cur.depositWaived) bits.push("deposit waived"); if(cur.lines.some(l=>l.floorSample)) bits.push("floor sample"); if(cur.lines.some(l=>l.takeNow)) bits.push("items taken today"); if(cur.lines.some(l=>l.price<0)) bits.push("negative line"); logAudit("sale",`${cur.number||""} ${money(T0.total)}${bits.length?" · "+bits.join(", "):""}`,{invoiceId:cur.id,amount:T0.total}); if(cur.depositWaived) logAudit("deposit_waived",cur.number||"",{invoiceId:cur.id}); }
  if(cur.fulfillment!=="mixed") cur.fulfillment=cur.delivery?"delivery":(cur.fulfillment==="delivery"?"now":(cur.fulfillment||"now"));
  if(cur.fulfillment==="now"&&cur.status!=="layaway") cur.lines.forEach(l=>{ if(!l.special) l.deliveredAt=cur.date; });
  if(cur.status!=="layaway") cur.lines.forEach(l=>{ if(!l.special&&!l.service&&(l.takeNow||lineFulfil(cur,l)==="now"&&cur.fulfillment==="mixed")){ l.deliveredAt=cur.date; l.takenAtSale=true; } });
  for(const l of cur.lines){ if(l.kit&&!l.special){ for(const k of l.kit){ const cp=byId("products",k.productId); if(cp){ const fl=stockMove(cp,-k.qty*l.qty,undefined); if(fl&&!l.locationId) l.locationId=fl; await save("products",cp); } } continue; } if(l.productId&&!l.special){ const p=byId("products",l.productId); if(p){ const fromLoc=stockMove(p,-l.qty,l.floorSample&&floorStock(p)>0?locations().find(x=>isDisplayLoc(x)&&stockAt(p,x.id)>0)?.id:undefined); if(fromLoc) l.locationId=fromLoc; if(p.floorSample){ p.floorSample=false; delete p.floorSampleSince; } await save("products",p); } } }
  const credit=cur.payments.filter(p=>p.method==="Store credit").reduce((a,p)=>a+p.amount,0); if(credit>0){ const c=byId("customers",cur.customerId); if(c){ c.credit=round2((c.credit||0)-credit); await save("customers",c); } }
  await save("invoices",cur);
  bumpTenantStats(); await upSold(cur);
  const inv=cur; const c=byId("customers",inv.customerId);
  if(inv.delivery){ const hasSpecial=inv.lines.some(l=>l.special); const leftForDelivery=inv.lines.filter(l=>!l.service&&!l.takeNow&&(inv.fulfillment!=="mixed"||lineFulfil(inv,l)==="delivery")); const opt=deliveryOptions().find(o=>o.id===inv.deliveryOptionId); if(leftForDelivery.length||inv.lines.some(l=>l.haulAway)) await save("deliveries",{id:uid(),invoiceId:inv.id,customerId:inv.customerId,date:"",winStart:c?.prefStart||"09:00",winEnd:c?.prefEnd||"17:00",truckId:"",status:inv.status==="layaway"?"awaiting":hasSpecial?"awaiting":"unscheduled",order:0,notes:c?.notes||"",haulAway:inv.lines.filter(l=>l.haulAway).length,setup:(opt?opt.setup!==false:true)||inv.lines.some(l=>/setup|assembly/i.test(l.name)),carrier:opt&&opt.carrier?opt.name:"",tracking:inv.tracking||"",method:opt?opt.name:"",lineIds:(inv.lines.some(l=>l.takeNow)||inv.fulfillment==="mixed")?leftForDelivery.map(l=>l.lineId):undefined}); }
  if(inv.fulfillment==="mixed"&&pickupLines(inv).length){ const p=await ensurePickup(inv,{plannedDate:inv.pickupDate||""}); if(p.status==="ready"&&!inv.lines.some(l=>l.special)) await addFollowup(inv.customerId,inv.id,"Ready for pickup",`${inv.number} — items are in stock and ready; let the customer know.`,todayISO()); }
  else if(!inv.delivery&&(inv.fulfillment==="pickup"||inv.lines.some(lineOpen))){ const p=await ensurePickup(inv,{plannedDate:inv.pickupDate||""}); if(p.plannedDate) await addFollowup(inv.customerId,inv.id+":pk","Pickup reminder","Remind the customer about tomorrow's pickup.",addDays(p.plannedDate,-1)); if(p.status==="ready"&&!p.plannedDate) await addFollowup(inv.customerId,inv.id,"Ready for pickup",`${inv.number} is ready — let the customer know.`,todayISO()); }
  else { await addFollowup(inv.customerId,inv.id,"Review request","Ask for a review after pickup.",addDays(todayISO(),14)); if(inv.lines.some(l=>l.mattress&&l.trial)) await addFollowup(inv.customerId,inv.id,"Sleep trial ending soon","Check in before the comfort trial ends.",addDays(todayISO(),Math.max(7,st.trialNights-14))); }
  if(inv.layaway) for(const p of inv.layaway.schedule) await addFollowup(inv.customerId,inv.id+":"+p.due,"Layaway payment due",`${money(p.amount)} due on ${inv.number}.`,p.due);
  if(inv.lines.some(l=>l.special)&&can("purchasing")) toast("Items ordered from suppliers now show under Purchasing — create the purchase orders there.");
  window.lastSaleId=inv.id; if(!partsPromptAfterSale(inv.id)&&storeSettings().afterSale!=="card") printInvoice(inv); cur=null; selLines.clear(); showMargin=false; toast("Sale completed — "+inv.number); if(view!=="pos") go("pos"); else render();
}
function bumpTenantStats(){ const t=currentTenant(); if(!t||session?.support) return; t.stats=Object.assign(t.stats||{},{invoices:S.invoices.filter(i=>!["void","quote"].includes(i.status)).length,staff:S.staff.length,lastActive:todayISO()}); saveTenant(t); }
function receiptText(inv){ const T=invTotals(inv); const st=storeSettings(); return `${st.name}\n${inv.status==="quote"?"Quote":"Invoice"} ${inv.number} · ${dateFmt(inv.date)}\n\n`+inv.lines.filter(l=>!l.groupId).map(l=>`${l.qty} x ${l.name} — ${money(l.price*l.qty)}`).join("\n")+(inv.groups||[]).map(g=>`\n${g.name} (package) — ${money(g.price)}\n`+inv.lines.filter(l=>l.groupId===g.id).map(l=>`   incl. ${l.qty} x ${l.name}`).join("\n")).join("")+`\n\nSubtotal ${money(T.sub)}${T.disc?`\nDiscount -${money(T.disc)}`:""}${T.delivery?`\nDelivery ${money(T.delivery)}`:""}\n${inv.taxName||"Tax"} ${money(T.tax)}\nTotal ${money(T.total)}\nPaid ${money(T.paid)}\nBalance ${money(T.balance)}\n\nThank you for shopping with ${st.name}.`; }
function custCopyCfg(){ const st=storeSettings(); return Object.assign({supplier:"code",hideSku:false,hideModel:false,hideCollection:false},st.custCopy||{}); }
function vendorDocLabel(l){ const p=l.productId?byId("products",l.productId):null; const v=p&&p.vendorId?byId("vendors",p.vendorId):null; if(!v) return ""; const c=custCopyCfg(); if(c.supplier==="none") return ""; if(c.supplier==="name") return v.name; return v.docCode||""; }
function printInvoice(inv,opts){ opts=opts||{}; const cc=custCopyCfg(); const hideSku=opts.hideSku||cc.hideSku; const hideModel=opts.hideModel||cc.hideModel; const hideLine=!!opts.hideLinePrices||!!opts.hideAllPrices; const hideAll=!!opts.hideAllPrices;
  const T=invTotals(inv), st=storeSettings(), c=byId("customers",inv.customerId); const groups=inv.groups||[];
  const warr=l=>l.asIs?"":l.warrantyYears?`<div style="font-size:11px;color:#444">${l.warrantyYears}-yr warranty${l.trial?` · ${st.trialNights}-night comfort trial`:""}</div>`:(l.trial?`<div style="font-size:11px;color:#444">${st.trialNights}-night comfort trial</div>`:"");
  const rows=inv.lines.filter(l=>!l.groupId).map(l=>`<tr><td>${hideSku?"":esc(l.sku)}${l.model&&!hideModel?`<br><small>${esc(l.model)}</small>`:""}${vendorDocLabel(l)?`<br><small>${esc(vendorDocLabel(l))}</small>`:""}</td><td>${esc(l.name)}${l.collection&&!cc.hideCollection?` <small>(${esc(l.collection)})</small>`:""}${l.special?` <small>(special order, est. ${dateShort(l.expected)})</small>`:""}${lineFunded(inv,l)?(()=>{const s=sourceById(inv,lineFundingId(inv,l));return s?` <small>(${s.type==="lease"?"LEASED":"FINANCED"} — ${esc(s.name)}${s.taxUpfront===false?", tax remitted by lessor":""})</small>`:""})():""}${l.appFee?" <small>(application fee collected in store, not taxed)</small>":""}${l.floorSample?" <small>(FLOOR SAMPLE — sold as displayed)</small>":""}${l.asIs?" <small><b>(SOLD AS-IS — all sales final, no warranty)</b></small>":""}${l.promo?` <small>(${esc(l.promo)} — was ${money(l.listPrice)})</small>`:""}${warr(l)}</td><td class="n">${l.qty}</td><td class="n">${hideLine?"":money(l.price)}</td><td class="n">${hideLine?"":money(l.price*l.qty)}</td></tr>`).join("")
   +groups.map(g=>`<tr class="pgroup"><td></td><td>${esc(g.name)}</td><td class="n"></td><td class="n">package</td><td class="n">${hideLine?"":money(g.price)}</td></tr>${inv.lines.filter(l=>l.groupId===g.id).map(l=>`<tr class="pgroup-item"><td>${hideSku?"":esc(l.sku)}${vendorDocLabel(l)?`<br><small>${esc(vendorDocLabel(l))}</small>`:""}</td><td>${esc(l.name)}${warr(l)}</td><td class="n">${l.qty}</td><td class="n">included</td><td class="n"></td></tr>`).join("")}`).join("");
  const __rule=docStyle().style==="classic"?`<div class="rule"></div>`:""; const __html=`<div class="page">${__rule}${!inv.partOf&&typeof payerParts==="function"&&payerParts(inv).length?`<div style="text-align:center;color:#C62828;font-weight:900;font-size:15px;letter-spacing:.08em;border:2px solid #C62828;padding:6px;margin:0 0 12px">DEALER COPY ONLY — NOT FOR LEASE / FINANCE COMPANIES<div style="font-size:10px;font-weight:600;letter-spacing:0">Use documents ${esc(inv.number)}-1 to ${esc(inv.number)}-${payerParts(inv).length} for the companies</div></div>`:""}${(()=>{ const ds=docStyle(); return ds.style==="modern"?`<div class="band"><div>${ds.showLogo?logoHTML(56):""}<h1>${esc(st.name)}</h1><div class="muted">${esc(st.address)}${st.phone?" · "+esc(st.phone):""}</div></div><div style="text-align:right"><h2>${inv.status==="quote"?"Quote":"Invoice"} ${esc(inv.number)}</h2>`:`<div style="display:flex;justify-content:space-between"><div>${ds.showLogo?logoHTML(56):""}<h1>${esc(st.name)}</h1><div>${esc(st.address)}${st.phone?" · "+esc(st.phone):""}</div></div><div style="text-align:right"><h2>${inv.status==="quote"?"Quote":"Invoice"} ${esc(inv.number)}</h2>`; })()}${inv.partOf?`<div style="font-size:11px;color:#555"><b>${esc(inv.partLabel||"")}</b> · document ${inv.partIndex} of ${inv.partCount} for sale ${esc(inv.partOf)}</div>`:""}<div>${dateFmt(inv.date)}</div><div>Sales: ${esc(splitLabel(inv))}</div></div></div>
  <p style="margin:18px 0">${c?.company?`<b>${esc(c.company)}</b><br>Attn: ${esc(c.name)}`:`<b>${esc(c?c.name:"Walk-in customer")}</b>`}<br>${esc(c?.address||"")}<br>${esc(c?.phone||"")} ${esc(c?.email||"")}</p>
  <table class="ptable"><tr><th>SKU</th><th>Description</th><th class="n">Qty</th><th class="n">Price</th><th class="n">Amount</th></tr>${rows}
  ${hideAll?`<tr><td colspan="5" class="n"><i>Prices on request — see your sales associate.</i></td></tr>`:`<tr><td colspan="4" class="n">Subtotal</td><td class="n">${money(T.sub)}</td></tr>${T.disc?`<tr><td colspan="4" class="n">Discount</td><td class="n">-${money(T.disc)}</td></tr>`:""}${T.delivery?`<tr><td colspan="4" class="n">Delivery</td><td class="n">${money(T.delivery)}</td></tr>`:""}<tr><td colspan="4" class="n">${esc(inv.taxName||"Sales tax")} ${inv.taxExempt?"(exempt)":inv.taxRate+"%"}${(T.fundings||[]).some(f=>!f.upfront)?" (not charged on items leased through "+esc((T.fundings||[]).filter(f=>!f.upfront).map(f=>f.src.name).join(", "))+" — the lessor remits it)":""}</td><td class="n">${money(T.tax)}</td></tr><tr><td colspan="4" class="n"><b>Total</b></td><td class="n"><b>${money(T.total)}</b></td></tr>${(T.fundings||[]).map(f=>`<tr><td colspan="4" class="n">Paid by ${esc(f.src.name)} (${f.src.type==="lease"?"lease-to-own":"financing"}${f.deliv?", incl. delivery":""}${f.upfront?", incl. tax "+money(f.tax):", no tax"}${f.appFee?", less "+money(f.appFee)+" application fee collected in store":""})</td><td class="n">${money(f.amount)}</td></tr>`).join("")}${(T.fundings||[]).length?`<tr><td colspan="4" class="n">Customer portion${T.custTax?" (incl. tax "+money(T.custTax)+")":""}</td><td class="n">${money(T.total-T.fundedAmount)}</td></tr>`:""}${inv.payments.map(p=>`<tr><td colspan="4" class="n">Paid — ${esc(p.method)}${p.card&&p.card.last4?" •••• "+esc(p.card.last4):""}${p.card&&p.card.auth?" auth "+esc(p.card.auth):""} ${dateShort(p.date)}</td><td class="n">-${money(p.amount)}</td></tr>`).join("")}<tr><td colspan="4" class="n"><b>Balance due</b></td><td class="n"><b>${money(T.balance)}</b></td></tr>`}</table>
  ${inv.financing?`<p style="margin-top:12px"><b>Financing:</b> ${esc(inv.financing.lender)} · ${inv.financing.months} monthly payments of about ${money(inv.financing.monthly)} at ${inv.financing.apr}% APR (estimate; your lender agreement governs).</p>`:""}
  ${inv.layaway?`<p style="margin-top:12px"><b>Layaway schedule:</b> ${inv.layaway.schedule.map(p=>`${dateShort(p.due)} ${money(p.amount)}${p.paid?" ✓":""}`).join(" · ")}. Items are held and delivered after the final payment.</p>`:""}
  ${inv.delivery?`<p style="margin-top:12px"><b>Delivery:</b> we'll call to confirm a window. Please clear a path to the room and note any damage on the delivery slip.</p>`:""}
  ${inv.status==="quote"&&inv.expires?`<p style="margin-top:12px"><b>This quote is valid until ${dateFmt(inv.expires)}.</b></p>`:""}${inv.notes?`<p style="margin-top:12px">${esc(inv.notes)}</p>`:""}${inv.lines.some(l=>l.asIs||l.floorSample)?`<p style="margin-top:14px;font-size:12px"><b>Floor sample / as-is acknowledgment:</b> I have inspected the item(s) marked floor sample or as-is and accept them in their current condition. Items marked AS-IS are sold without warranty and are not returnable or exchangeable.<br><br>Customer signature: ____________________________ &nbsp; Date: ____________</p>`:""}${termsHTML(inv)}<p style="margin-top:14px;font-size:11px">${esc(st.footer)}</p>${inv.signature?`<p style="font-size:11px">Signed by ${esc(inv.signedName||"")} on ${dateFmt(inv.signedAt)} (terms v${esc(inv.termsVersion||"")}).</p>`:""}</div>${docStyle().footerNote?`<p style="margin-top:14px;font-size:11px;color:#555;border-top:1px solid #ddd;padding-top:6px">${esc(docStyle().footerNote)}</p>`:""}${inv.partOf?partSignatureBlockHTML(inv):""}${termsCfg().signaturePage&&inv.status!=="quote"&&!window._noSigPage?signaturePageHTML(inv):""}`; if(opts.returnHtml) return __html; printHTML(__html,(inv.status==="quote"?"Quote ":"Invoice ")+inv.number);
}

