let invFilter="all", invListQ="";
function renderInvoices(){
  const q=invListQ.toLowerCase(); const fulfilMatch=i=>{ if(!invFulfil||invFulfil==="all") return true; const l=fulfillmentLabel(i); if(invFulfil==="delivered") return /^Delivered/.test(l); if(invFulfil==="pickedup") return /^Picked up|^Taken at sale/.test(l); if(invFulfil==="partial") return /^Partially/.test(l); if(invFulfil==="pending") return !!l&&!/^Delivered|^Picked up|^Taken at sale/.test(l); if(invFulfil==="remote") return !!i.signedRemote&&!i.remoteReviewed; return true; };
  const rows=S.invoices.filter(i=>(invFilter==="all"||i.status===invFilter)&&fulfilMatch(i)&&(!q||[i.number,custName(i.customerId),staffName(i.salesId)].join(" ").toLowerCase().includes(q))).slice().sort((a,b)=>(b.completedAt||0)-(a.completedAt||0)||b.date.localeCompare(a.date));
  return `<div class="topbar"><h1>Invoices</h1><span class="muted">Every sale and quote — look up, print, take payments, returns</span><input type="search" id="q_invListQ" placeholder="Search number, customer…" value="${esc(invListQ)}" oninput="invListQ=this.value;render()" style="max-width:260px"><select style="max-width:170px" onchange="invFilter=this.value;render()">${["all","open","paid","financed","layaway","quote","void"].map(s=>`<option value="${s}" ${invFilter===s?"selected":""}>${s==="all"?"All statuses":s[0].toUpperCase()+s.slice(1)}</option>`).join("")}</select>${isManager()?dd("More",[["Export invoices (CSV)","exportCSV('invoices')"]]):""}<button class="btn p" onclick="cur=null;go('pos')">New sale</button></div>
  <div class="sub">${[["all","All"],["remote","✍ Signed remotely — to review"],["pending","Still owed to customer"],["partial","Partly delivered / picked up"],["delivered","Delivered"],["pickedup","Picked up / taken"]].map(([k,l])=>`<button class="${(invFulfil||"all")===k?"on":""}" onclick="invFulfil='${k}';render()">${l} (${S.invoices.filter(i=>!["void","quote","draft"].includes(i.status)).filter(i=>{ const l2=fulfillmentLabel(i); if(k==="all") return true; if(k==="delivered") return /^Delivered/.test(l2); if(k==="pickedup") return /^Picked up|^Taken at sale/.test(l2); if(k==="partial") return /^Partially/.test(l2); if(k==="pending") return !!l2&&!/^Delivered|^Picked up|^Taken at sale/.test(l2); if(k==="remote") return !!i.signedRemote&&!i.remoteReviewed; return true; }).length})</button>`).join("")}</div>
  <div class="card">${table(rows,[["Number",i=>`<a href="#" onclick="openInvoice('${i.id}');return false"><b>${esc(i.number)}</b></a>`],["Date",i=>dateShort(i.date)],["Customer",i=>esc(custName(i.customerId))],["Sales",i=>esc(splitLabel(i))],["Items",i=>`${i.lines.reduce((a,l)=>a+l.qty,0)}${i.lines.some(l=>l.special&&l.specialStatus!=="arrived")?' <span class="tag warn">special</span>':""}`],["Fulfillment",i=>fulfillmentTag(i)],["Total",i=>money(invTotals(i).total),"n"],["Balance",i=>money(invTotals(i).balance),"n"],["Status",i=>i.status==="quote"&&i.expires&&i.expires<todayISO()?statusTag("expired"):statusTag(i.status)]],"No invoices yet.")}</div>`;
}
function editInvoiceDetails(id){ const inv=byId("invoices",id); if(!inv||inv.status==="void") return; const c=byId("customers",inv.customerId); modal(`<h2>Edit ${esc(inv.number)} — details</h2><p class="muted small">Change the notes, the customer or the salesperson. To change items or prices, use <b>Edit items</b> on the invoice.</p><div class="grid g2"><div class="field"><label class="f">Customer</label><select id="ei_cust">${S.customers.slice().sort((a,b)=>(a.name||"").localeCompare(b.name||"")).map(x=>`<option value="${x.id}" ${x.id===inv.customerId?"selected":""}>${esc(custDisplay(x))}${x.phone?" · "+esc(x.phone):""}</option>`).join("")}</select></div><div class="field"><label class="f">Salesperson ${isManager()?"":"<span class=\"muted\">(manager)</span>"}</label><select id="ei_sales" ${isManager()?"":"disabled"}><option value="">—</option>${S.staff.filter(s=>s.active!==false&&["sales","manager","owner","cashier"].includes(s.role)).map(s=>`<option value="${s.id}" ${s.id===inv.salesId?"selected":""}>${esc(s.name)}</option>`).join("")}</select></div></div><div class="field"><label class="f">Notes on invoice (print on the customer copy)</label><textarea id="ei_notes" rows="3">${esc(inv.notes||"")}</textarea></div><div class="field"><label class="f">Internal note (staff only — never printed)</label><textarea id="ei_int" rows="2">${esc(inv.internalNote||"")}</textarea></div><div class="actions"><button class="btn" onclick="closeModal();openInvoice('${id}')">Cancel</button><button class="btn p" onclick="saveInvoiceDetails('${id}')">Save</button></div>`); }
async function saveInvoiceDetails(id){ const inv=byId("invoices",id); const before={customerId:inv.customerId,salesId:inv.salesId,notes:inv.notes||"",internalNote:inv.internalNote||""}; inv.customerId=fv("ei_cust")||inv.customerId; if(isManager()&&document.getElementById("ei_sales")) inv.salesId=fv("ei_sales")||inv.salesId; inv.notes=fv("ei_notes"); inv.internalNote=fv("ei_int"); await save("invoices",inv); for(const d of S.deliveries.filter(d=>d.invoiceId===inv.id&&d.customerId!==inv.customerId)){ d.customerId=inv.customerId; await save("deliveries",d); } const ch=[]; if(before.customerId!==inv.customerId) ch.push("customer"); if(before.salesId!==inv.salesId) ch.push("salesperson"); if(before.notes!==inv.notes) ch.push("notes"); if(before.internalNote!==inv.internalNote) ch.push("internal note"); if(ch.length) logAudit("edit",`${inv.number}: ${ch.join(", ")} changed`,{invoiceId:inv.id}); closeModal(); openInvoice(id); toast("Saved"); }
function editInvoiceItems(id){ const inv=byId("invoices",id); if(!inv||inv.status==="void") return; if(!isManager()&&!has("editInvoice")) return denied("edit a completed invoice — ask a manager"); const delivered=inv.lines.filter(l=>l.deliveredAt&&!l.service); if(delivered.length) return modal(`<h2>Items already delivered</h2><p class="muted">${delivered.length} item${delivered.length===1?"":"s"} on ${esc(inv.number)} ${delivered.length===1?"has":"have"} already been delivered or taken, so the sale can't be rebuilt in the register. You can still: return or exchange those items (<b>Return / exchange</b>), ring additional items as a new sale for the same customer, or change notes, customer and salesperson with <b>Edit details</b>.</p><div class="actions"><button class="btn" onclick="closeModal();openInvoice('${id}')">Back</button></div>`); confirmDo(`Reopen ${inv.number} in the register? Stock for its items is put back while you edit, payments and the invoice number are kept, and the sale is re-completed when you press Complete. This is logged.`,()=>{ cur=JSON.parse(JSON.stringify(inv)); cur.editingId=inv.id; cur.status="draft"; cur.lines.forEach(l=>{ delete l.deliveredAt; delete l.takenAtSale; }); closeModal(); go("pos"); toast(`Editing ${inv.number} — press Complete sale when done`); }); }
function openInvoice(id){
  const inv=byId("invoices",id); if(!inv) return; const T=invTotals(inv); const c=byId("customers",inv.customerId); const st=storeSettings(); const del=S.deliveries.find(d=>d.invoiceId===id&&d.kind!=="pickup"); const rets=S.returns.filter(r=>r.invoiceId===id);
  const warrantyEnd=l=>{ if(!l.warrantyYears||l.asIs) return ""; const start=l.deliveredAt||inv.date; return addDays(start,Math.round(l.warrantyYears*365)); };
  const pk=pickupOf(inv);
  modal(`<h2>${esc(inv.number)} ${statusTag(inv.status)} ${fulfillmentTag(inv)}</h2><p class="muted">${dateFmt(inv.date)} · ${c?`<a href="#" onclick="openCustomer('${c.id}');return false">${esc(c.name)}</a>`:"Walk-in"} · ${esc(splitLabel(inv))}${inv.rungBy&&inv.rungBy!==inv.salesId?` · rung up by ${esc(staffName(inv.rungBy))}${inv.verifiedBy?" (PIN confirmed)":""}`:""}</p>${["void","quote","draft"].includes(inv.status)?"":fulfillmentStepper(inv)}${!["void","quote","draft","layaway"].includes(inv.status)&&inv.lines.some(l=>lineOpen(l))&&inv.lines.some(l=>l.deliveredAt)?`<div class="notice" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><span style="flex:1">Outstanding: ${inv.lines.filter(lineOpen).map(l=>`${l.qty}× ${esc(l.name)}${l.expected?" (ETA "+dateShort(l.expected)+")":""}`).join(", ")}</span><button class="btn s" onclick="setEta('${id}')">Set ETA / notify</button></div>`:""}
  <div class="tblwrap"><table><thead><tr><th>Item</th><th class="n">Qty</th><th class="n">Price</th><th>Status</th></tr></thead><tbody>${inv.lines.map(l=>`<tr><td>${esc(l.name)}${l.takenAtSale?' <span class="tag ok">taken at sale</span>':""}${lineFunded(inv,l)?(()=>{const s=sourceById(inv,lineFundingId(inv,l));return s?` <span class="tag info">${s.type==="lease"?"leased":"financed"} · ${esc(s.name)}</span>`:""})():""}${l.floorSample?' <span class="tag warn">floor sample</span>':""}${l.asIs?' <span class="tag bad">as-is</span>':""}${l.groupId?` <span class="tag">${esc((inv.groups||[]).find(g=>g.id===l.groupId)?.name||"pkg")}</span>`:""}${warrantyEnd(l)?`<div class="muted small">Warranty to ${dateShort(warrantyEnd(l))}${l.trial&&l.deliveredAt?` · trial to ${dateShort(addDays(l.deliveredAt,st.trialNights))}`:""}</div>`:""}</td><td class="n">${l.qty}</td><td class="n">${l.groupId?"incl.":money(l.price)}</td><td>${l.deliveredAt?statusTag(inv.delivery?"delivered":"picked up")+` <span class="muted small">${dateShort(l.deliveredAt)}</span>`:l.special?statusTag(l.specialStatus||"pending")+(l.expected&&l.specialStatus!=="arrived"?` <span class="muted small">${dateShort(l.expected)}</span>`:""):inv.status==="layaway"?statusTag("held"):(inv.delivery?'<span class="tag info">for delivery</span>':'<span class="tag info">held for pickup</span>')+(l.expected?` <span class="muted small">ETA ${dateShort(l.expected)}</span>`:"")}</td></tr>`).join("")}${(inv.groups||[]).map(g=>`<tr><td><b>${esc(g.name)}</b> package</td><td></td><td class="n"><b>${money(g.price)}</b></td><td></td></tr>`).join("")}</tbody></table></div>
  ${inv.signedRemote?`<div class="notice" style="margin:8px 0;${inv.remoteReviewed?"":"background:var(--mint2);border-color:var(--green)"}"><div class="row" style="gap:8px;align-items:center;flex-wrap:wrap"><span style="flex:1"><b>✍ Signed remotely</b> by ${esc(inv.signedName||"")} on ${dateFmt(inv.signedAt)}${(byId("customers",inv.customerId)||{}).idPhoto?" · ID photos received":""}${inv.selfieCheck?" · photo check received":""}${inv.documents&&inv.documents.length?" · "+inv.documents.length+" document(s)":""}. ${inv.remoteReviewed?"Reviewed by "+esc(staffName(inv.remoteReviewedBy))+".":"Review the signature, ID and photos below."}</span>${inv.remoteReviewed?"":`<button class="btn s p" onclick="(async()=>{ const i=byId('invoices','${id}'); i.remoteReviewed=true; i.remoteReviewedBy=session.staffId; i.remoteReviewedAt=todayISO(); await save('invoices',i); logAudit('sign_request',i.number+': remote signature reviewed'); openInvoice('${id}'); })()">Mark reviewed</button>`}<button class="btn s" onclick="askRedo('${id}')" title="Send the customer a request to redo part of it">Ask customer to redo…</button></div></div>`:""}${partsPanelHTML(inv)}${typeof selfieCheckHTML==="function"?selfieCheckHTML(inv):""}${typeof invoiceDocsHTML==="function"?invoiceDocsHTML(inv):""}
  <div class="grid g2" style="margin-top:12px"><div><div class="tot"><span>Subtotal</span><span>${money(T.sub)}</span></div>${T.disc?`<div class="tot"><span>Discount</span><span>-${money(T.disc)}</span></div>`:""}${T.delivery?`<div class="tot"><span>Delivery</span><span>${money(T.delivery)}</span></div>`:""}<div class="tot"><span>${esc(inv.taxName||"Tax")}${inv.taxExempt?" (exempt)":" "+inv.taxRate+"%"}${T.funding&&T.funding.taxUpfront===false?" · customer items only":""}</span><span>${money(T.tax)}</span></div>${(T.fundings||[]).map(f=>`<div class="tot muted small"><span>${esc(f.src.name)} (${f.src.type==="lease"?"lease-to-own":"financing"}) pays${f.upfront?"":" · no tax"}${fundingApproved(inv,f.src)!==null?" · approved "+money(fundingApproved(inv,f.src)):""}</span><span>${money(f.amount)}</span></div>`).join("")}${(T.fundings||[]).length?`<div class="tot muted small"><span>Customer pays</span><span>${money(T.total-T.fundedAmount)}</span></div>`:""}<div class="tot"><span><b>Total</b></span><b>${money(T.total)}</b></div><div class="tot"><span>Paid</span><span>${money(T.paid)}</span></div><div class="tot"><span><b>Balance</b></span><b>${money(T.balance)}</b></div>${has("margin")?`<div class="tot muted small"><span>Margin</span><span>${pct(T.marginPct)}${seesCost()?" · "+money(T.margin):""}</span></div>`:""}</div>
  <div><b class="small">Payments</b>${inv.payments.map(p=>`<div class="muted small">${dateShort(p.date)} · ${esc(p.method)} · ${money(p.amount)}</div>`).join("")||`<div class="muted small">None yet.</div>`}
  ${inv.layaway?`<b class="small" style="display:block;margin-top:8px">Layaway schedule</b>${inv.layaway.schedule.map(p=>`<div class="small">${dateShort(p.due)} · ${money(p.amount)} ${p.paid?'<span class="tag ok">paid</span>':p.due<todayISO()?'<span class="tag bad">overdue</span>':""}</div>`).join("")}`:""}
  ${inv.financing?`<div class="muted small" style="margin-top:8px">${esc(inv.financing.lender)} · ${inv.financing.months} mo · ${money(inv.financing.monthly)}/mo</div>`:""}
  ${rets.length?`<b class="small" style="display:block;margin-top:8px">Returns</b>${rets.map(r=>`<div class="small">${esc(r.number)} · ${esc(r.reason)} · ${money(r.refundTotal)}</div>`).join("")}`:""}</div></div>
  ${T.balance>0.005&&!["void","quote"].includes(inv.status)?`<div class="row" style="margin-top:10px"><select id="op_method">${tenderTypes().map(m=>`<option>${esc(m)}</option>`).join("")}${c?.credit>0?`<option value="Store credit">Store credit (${money(c.credit)})</option>`:""}</select><input type="number" step="0.01" id="op_amt" placeholder="${T.balance.toFixed(2)}"><button class="btn fx p" onclick="payInvoice('${id}')">Record payment</button></div>`:""}
  ${inv.notes?`<p class="muted" style="margin-top:8px">${esc(inv.notes)}</p>`:""}
  ${(()=>{ const openL=inv.lines.some(lineOpen); const live=!["void","quote"].includes(inv.status); const more=[];
  if(openL&&!["void","quote","draft"].includes(inv.status)) more.push(["Print labels for this order",`labelsForOrder('${id}')`]);
  if(c?.email) more.push(["Email receipt",`window.location.href='mailto:${esc(c.email)}?subject=${encodeURIComponent((inv.status==="quote"?"Quote ":"Receipt ")+inv.number+" — "+st.name)}&body=${encodeURIComponent(receiptText(inv))}'`]);
  if(c?.phone) more.push(["Text receipt",`window.location.href='sms:${esc(c.phone)}?&body=${encodeURIComponent(receiptText(inv))}'`]);
  if(live&&!inv.delivery&&pk&&pk.status!=="pickedup") more.push(["Change to delivery",`convertPickupToDelivery('${id}')`]);
  if(live&&!inv.delivery&&!pk) more.push(["Add delivery",`convertToDelivery('${id}')`]);
  if(live&&inv.delivery&&del&&!["loaded","out","delivered"].includes(del.status)) more.push(["Change to pickup",`convertToPickup('${id}')`]);
  if(live&&openL&&inv.lines.some(l=>lineOpen(l)&&lineBlocked(l))&&inv.status!=="layaway") more.push(["Set ETA / notify customer",`setEta('${id}')`]);
  if(more.length) more.push(null);
  if(["paid","open","financed"].includes(inv.status)&&has("returns")) more.push(["Return / exchange",`startReturn('${id}')`]);
  if(live) more.push(["Warranty claim",`newClaim('${inv.customerId}','${id}')`]);
  if(live&&has("void")) more.push(["Void this invoice",`confirmDo('Void this invoice and return stock?',()=>voidInvoice('${id}'))`]);
  let next="";
  if(inv.status==="quote") next=`<button class="btn p" onclick="cur=JSON.parse(JSON.stringify(byId('invoices','${id}')));cur.status='draft';cur.terms='now';closeModal();go('pos')">Open in register</button>`;
  else if(live&&inv.delivery&&del&&["unscheduled","missed"].includes(del.status)) next=`<button class="btn p" onclick="closeModal();editDelivery('${del.id}')">Schedule delivery</button>`;
  else if(live&&!inv.delivery&&pk&&pk.status!=="pickedup") next=`${(pk.status==="ready"||pk.status==="partready")&&c?.phone?`<a class="btn" href="sms:${esc(c.phone)}?&body=${encodeURIComponent(readyText(inv))}" onclick="markNotified('${pk.id}')">Text: ready</a>`:""}<button class="btn p" onclick="closeModal();completePickup('${pk.id}')" ${pk.status==="ready"||pk.status==="partready"?"":"disabled"}>${pk.status==="partready"?"Pick up what's in":"Complete pickup"}</button>`;
  else if(live&&!inv.delivery&&!pk&&openL) next=`<button class="btn p" onclick="(async()=>{await ensurePickup(byId('invoices','${id}'));closeModal();openInvoice('${id}')})()">Hold for pickup</button>`;
  return `<div class="actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn" onclick="printInvoice(byId('invoices','${id}'))">Print</button>${dd("Customer copy",[["Without line prices (total only)",`printInvoice(byId('invoices','${id}'),{hideLinePrices:true})`],["Without any prices",`printInvoice(byId('invoices','${id}'),{hideAllPrices:true})`],["Without SKU / model numbers",`printInvoice(byId('invoices','${id}'),{hideSku:true,hideModel:true})`],["Plain — no prices, no SKUs",`printInvoice(byId('invoices','${id}'),{hideAllPrices:true,hideSku:true,hideModel:true})`]])}${inv.status!=="quote"&&inv.status!=="void"?`<button class="btn s" onclick="editInvoiceDetails('${id}')" title="Notes, customer, salesperson">Edit details</button>${isManager()||has("editInvoice")?`<button class="btn s" onclick="editInvoiceItems('${id}')" title="Reopen in the register to change items or prices">Edit items</button>`:""}`:""}${inv.status!=="quote"?`<button class="btn ${inv.signature?"":"s"}" onclick="invoiceSign('${id}')">${inv.signature?(inv.signedRemote?"Signed remotely ✓":"Signed ✓"):"Sign here"}</button>${!inv.signature?`<button class="btn s" onclick="sendForSignature('${id}')" title="Send a link the customer signs on their own phone">Send for signature</button>`:""}`:""}${more.length?dd("More",more):""}${next}</div>`; })()}`,true);
}
async function markPickedUp(id){ const inv=byId("invoices",id); const today=todayISO(); let n=0; inv.lines.forEach(l=>{ if(!l.deliveredAt&&(!l.special||l.specialStatus==="arrived")){ l.deliveredAt=today; n++; } }); await save("invoices",inv); for(const f of S.followups.filter(f=>f.status==="open"&&f.invoiceId===id&&f.type==="Special order arrived")){ f.status="done"; f.doneAt=today; await save("followups",f); } if(inv.lines.some(l=>l.mattress&&l.trial&&l.deliveredAt===today)) await addFollowup(inv.customerId,id,"Sleep trial ending soon","Check in before the comfort trial ends.",addDays(today,Math.max(7,storeSettings().trialNights-14))); closeModal(); render(); toast(`${n} item${n===1?"":"s"} marked picked up`); }
async function payInvoice(id){ if(!requirePerm("payments","record payments on invoices")) return; const inv=byId("invoices",id); const T=invTotals(inv); const method=fv("op_method"); let amt=fnum("op_amt")||T.balance; if(amt<=0) return; logAudit("payment",`${inv.number} ${method} ${money(Math.min(amt,T.balance))}`,{invoiceId:id,amount:Math.min(amt,T.balance)}); if(method==="Card"&&cardPanelOn()){ window._cardTarget=id; return cardPanel(Math.min(amt,T.balance)); } if(method==="Store credit"){ const c=byId("customers",inv.customerId); amt=Math.min(amt,c?.credit||0); if(amt<=0) return toast("No store credit available.",true); c.credit=round2(c.credit-amt); await save("customers",c); } if(amt>T.balance) amt=T.balance; inv.payments.push({method,amount:round2(amt),date:todayISO(),by:session.staffId});
  if(inv.layaway){ let left=round2(amt); for(const p of inv.layaway.schedule){ if(p.paid) continue; if(left>=p.amount-0.005){ p.paid=true; left=round2(left-p.amount); const f=S.followups.find(f=>f.status==="open"&&f.invoiceId===id+":"+p.due); if(f){ f.status="done"; await save("followups",f);} } else break; } }
  const bal=invTotals(inv).balance; if(bal<=0.005){ inv.status="paid"; if(inv.layaway){ for(const d of S.deliveries.filter(x=>x.invoiceId===id&&x.kind!=="pickup"&&x.status==="awaiting")){ if(!itemsOf(d).some(l=>lineOpen(l)&&lineBlocked(l))){ d.status="unscheduled"; await save("deliveries",d); } } await refreshPickup(inv); for(const p of inv.layaway.schedule) p.paid=true; for(const f of S.followups.filter(f=>f.status==="open"&&f.invoiceId.startsWith(id+":"))){ f.status="done"; await save("followups",f);} } }
  await save("invoices",inv); closeModal(); render(); toast("Payment recorded"+(bal<=0.005?" — paid in full":"")); }
async function voidInvoice(id){ if(!requirePerm("void","void invoices")) return; const inv=byId("invoices",id); logAudit("void",`${inv.number} ${money(invTotals(inv).total)}`,{invoiceId:inv.id,amount:invTotals(inv).total}); inv.status="void"; inv.voidedBy=session.staffId; inv.voidedAt=todayISO();
  { const notes=[]; for(const l of inv.lines){ if(!l.poId) continue; const po=byId("purchaseOrders",l.poId); if(!po||po.status==="cancelled") continue; const pls=po.lines.filter(x=>x.lineId===l.lineId); if(!pls.length) continue; if(po.status==="draft"){ po.lines=po.lines.filter(x=>x.lineId!==l.lineId); if(!po.lines.length){ po.status="cancelled"; notes.push(po.number+" cancelled (nothing left on it)"); } else notes.push(l.name+" removed from draft "+po.number); } else { pls.forEach(x=>{ x.invoiceId=null; x.lineId=null; x.note="Customer order "+inv.number+" was voided — receive into stock or cancel with the vendor"; x.voidedFrom=inv.number; }); po.notes=(po.notes?po.notes+" · ":"")+"Voided sale "+inv.number+": "+pls.map(x=>x.desc).join(", ")+" now for stock"; notes.push(l.name+" on "+po.number+" now goes to stock when it arrives"); } await save("purchaseOrders",po); } if(notes.length) setTimeout(()=>toast("Purchase orders updated: "+notes.join("; "),true),300); } for(const l of inv.lines){ if(l.kit&&!l.special){ for(const k of l.kit){ const cp=byId("products",k.productId); if(cp){ stockMove(cp,k.qty*l.qty,undefined); await save("products",cp); } } continue; } if(l.productId&&!l.special){ const p=byId("products",l.productId); if(p){ stockMove(p,l.qty,undefined); await save("products",p); } } } for(const d of S.deliveries.filter(x=>x.invoiceId===id&&!["delivered","pickedup"].includes(x.status))) await remove("deliveries",d.id); for(const f of S.followups.filter(f=>f.status==="open"&&String(f.invoiceId).startsWith(id))){ f.status="done"; await save("followups",f);} await save("invoices",inv); closeModal(); render(); }
async function convertToDelivery(id){ const inv=byId("invoices",id); if(!inv.customerId){ return modal(`<h2>Who is this delivery for?</h2><div class="field"><label class="f">Customer</label><select id="cd_c">${opts(S.customers,"",x=>x.name,x=>x.id,"Choose…")}</select></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="(async()=>{if(!fv('cd_c'))return;const inv=byId('invoices','${id}');inv.customerId=fv('cd_c');await save('invoices',inv);convertToDelivery('${id}')})()">Continue</button></div>`); } const c=byId("customers",inv.customerId); inv.delivery=true; await save("invoices",inv); const d=await save("deliveries",{id:uid(),invoiceId:inv.id,customerId:inv.customerId,date:"",winStart:c?.prefStart||"09:00",winEnd:c?.prefEnd||"17:00",truckId:"",status:inv.lines.some(l=>l.special&&l.specialStatus!=="arrived")?"awaiting":"unscheduled",order:0,notes:c?.notes||"",haulAway:inv.lines.filter(l=>l.haulAway).length}); closeModal(); editDelivery(d.id); }

/* ============================================================
   SERVICE: returns & exchanges, warranty claims, follow-ups
   ============================================================ */
let serviceTab="followups";
function exportDeliveredCustomers(){ const since=addDays(todayISO(),-7); const rows=[]; const seen=new Set(); for(const d of S.deliveries){ if(d.status!=="delivered"&&d.status!=="pickedup") continue; const when=d.deliveredAt||d.pickedUpAt||""; if(!when||when<since) continue; const c=byId("customers",d.customerId); if(!c||seen.has(c.id)) continue; seen.add(c.id); const inv=byId("invoices",d.invoiceId); rows.push([c.first||c.name.split(" ")[0],c.last||c.name.split(" ").slice(1).join(" "),c.phone||"",c.email||"",inv?inv.number:"",when,d.kind==="pickup"?"pickup":"delivery",d.survey?d.survey.score:""]); } if(!rows.length) return toast("No completed deliveries or pickups in the last 7 days.",true); saveFile(`delivered-customers-${todayISO()}.csv`,["First name,Last name,Phone,Email,Invoice,Completed,How,Feedback"].concat(rows.map(r=>r.map(x=>`"${String(x).replace(/"/g,'""')}"`).join(","))).join("\n")); toast(`${rows.length} customer${rows.length===1?"":"s"} exported — upload to ${storeSettings().messaging?.provider||"your messaging system"} for review requests`); }
function renderService(){
  const today=todayISO(); const fus=S.followups.filter(f=>f.status==="open").sort((a,b)=>(a.due||"").localeCompare(b.due||""));
  const tabs=`<div class="sub"><button class="${serviceTab==="followups"?"on":""}" onclick="serviceTab='followups';render()">Follow-ups (${fus.filter(f=>f.due<=today).length} due)</button><button class="${serviceTab==="returns"?"on":""}" onclick="serviceTab='returns';render()">Returns & exchanges</button><button class="${serviceTab==="claims"?"on":""}" onclick="serviceTab='claims';render()">Warranty claims (${S.claims.filter(x=>!["replaced","denied","closed"].includes(x.status)).length})</button><button class="${serviceTab==="trials"?"on":""}" onclick="serviceTab='trials';render()">Sleep trials</button></div>`;
  const exportBtn=`<button class="btn" onclick="exportDeliveredCustomers()" title="Completed deliveries and pickups — upload to Podium / your messaging system for review requests">Export delivered customers</button>`;
  let body="";
  if(serviceTab==="followups") body=`<div class="card">${table(fus,[["Due",f=>`<span class="tag ${f.due<today?"bad":f.due===today?"warn":""}">${dateShort(f.due)}</span>`],["Customer",f=>`<b>${esc(custName(f.customerId))}</b><div class="muted">${esc(byId("customers",f.customerId)?.phone||"")}</div>`],["Type",f=>esc(f.type)],["Note",f=>esc(f.note)],["",f=>`<button class="btn s p" onclick="openFollowup('${f.id}')">Open</button>`]],"No open follow-ups. They're created automatically after sales, deliveries, layaway schedules and special orders.")}</div>`;
  if(serviceTab==="returns") body=`<div class="card"><p class="muted">Start a return or exchange from the invoice (Invoices → open → Return / exchange).</p>${table(S.returns.slice().sort((a,b)=>b.date.localeCompare(a.date)),[["Return",r=>`<b>${esc(r.number)}</b>`],["Date",r=>dateShort(r.date)],["Invoice",r=>`<a href="#" onclick="openInvoice('${r.invoiceId}');return false">${esc(byId("invoices",r.invoiceId)?.number||"")}</a>`],["Customer",r=>esc(custName(r.customerId))],["Reason",r=>esc(r.reason)],["Items",r=>r.lines.map(l=>`${l.qty}× ${esc(l.name)} (${esc(l.condition)})`).join(", ")],["Refund",r=>`${money(r.refundTotal)}<div class="muted small">${esc(r.method)}</div>`,"n"],["",r=>`<button class="btn s" onclick="printReturn('${r.id}')">Print</button>`]],"No returns yet.")}</div>`;
  if(serviceTab==="claims") body=`<div class="card">${table(S.claims.slice().sort((a,b)=>b.date.localeCompare(a.date)),[["Claim",x=>`<b>${esc(x.number)}</b>`],["Date",x=>dateShort(x.date)],["Customer",x=>esc(custName(x.customerId))],["Item",x=>esc(x.itemName)],["Vendor",x=>esc(vendName(x.vendorId))],["Issue",x=>esc(x.issue)],["Status",x=>statusTag(x.status)],["",x=>`<button class="btn s" onclick="openClaim('${x.id}')">Open</button>`]],"No warranty claims.")}</div>`;
  if(serviceTab==="trials"){ const st=storeSettings(); const rows=S.invoices.flatMap(i=>i.lines.filter(l=>l.mattress&&l.trial&&i.status!=="void").map(l=>({i,l,start:l.deliveredAt||(i.delivery?null:i.date)}))).map(x=>Object.assign(x,{end:x.start?addDays(x.start,st.trialNights):null})).filter(x=>!x.end||x.end>=addDays(today,-30)).sort((a,b)=>String(a.end).localeCompare(String(b.end)));
    body=`<div class="card"><p class="muted">${st.trialNights}-night comfort trials. ${st.protectorRequired?"A mattress protector purchase is required for comfort exchanges.":""}</p>${table(rows,[["Customer",x=>`<b>${esc(custName(x.i.customerId))}</b><div class="muted">${esc(x.i.number)}</div>`],["Mattress",x=>`${esc(x.l.name)} <span class="muted">${esc(x.l.size)}</span>`],["Trial started",x=>x.start?dateShort(x.start):'<span class="tag warn">awaiting delivery</span>'],["Ends",x=>x.end?`<span class="tag ${x.end<today?"":daysBetween(today,x.end)<=14?"warn":"ok"}">${dateShort(x.end)}</span>`:"—"],["Protector",x=>x.i.lines.some(isProtector)?'<span class="tag ok">yes</span>':'<span class="tag bad">no</span>'],["",x=>`${has("returns")?`<button class="btn s" onclick="startReturn('${x.i.id}')">Comfort exchange</button>`:""}`]],"No mattresses on trial.")}</div>`; }
  return `<div class="topbar"><h1>Service</h1>${can("service")?`${exportBtn}<button class="btn" onclick="manualFollowup()">Add follow-up</button><button class="btn p" onclick="newClaim()">New warranty claim</button>`:""}</div>${tabs}${body}`;
}
function manualFollowup(){ modal(`<h2>Add follow-up</h2><div class="field"><label class="f">Customer</label><select id="mf_c">${opts(S.customers,"",x=>x.name,x=>x.id,"Choose…")}</select></div><div class="grid g2"><div class="field"><label class="f">Type</label><select id="mf_t">${optsList(["Call back","Delivery check-in","Special order arrived","Review request","Sleep trial ending soon","Layaway payment due","Other"],"Call back")}</select></div><div class="field"><label class="f">Due</label><input type="date" id="mf_d" value="${addDays(todayISO(),1)}"></div></div><div class="field"><label class="f">Note</label><input type="text" id="mf_n"></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="(async()=>{if(!fv('mf_c'))return toast('Choose a customer',true);await save('followups',{id:uid(),customerId:fv('mf_c'),invoiceId:'manual:'+uid(),type:fv('mf_t'),note:fv('mf_n'),due:fv('mf_d'),status:'open',created:todayISO()});closeModal();render()})()">Add</button></div>`); }
function startReturn(invId){ if(!requirePerm("returns","process returns and refunds")) return;
  const inv=byId("invoices",invId); const st=storeSettings(); const c=byId("customers",inv.customerId);
  const returned={}; S.returns.filter(r=>r.invoiceId===invId).forEach(r=>r.lines.forEach(l=>returned[l.lineId]=(returned[l.lineId]||0)+l.qty));
  const lines=inv.lines.filter(l=>!l.service&&l.qty-(returned[l.lineId]||0)>0);
  if(!lines.length) return toast("Everything on this invoice has already been returned.",true);
  const trialInfo=l=>{ if(!l.mattress||!l.trial) return ""; const start=l.deliveredAt||(inv.delivery?null:inv.date); if(!start) return '<span class="tag warn">not delivered yet</span>'; const end=addDays(start,st.trialNights); return end>=todayISO()?`<span class="tag ok">trial to ${dateShort(end)}</span>`:`<span class="tag bad">trial ended ${dateShort(end)}</span>`; };
  modal(`<h2>Return / exchange — ${esc(inv.number)}</h2><p class="muted">${esc(c?.name||"Walk-in")} · sold ${dateFmt(inv.date)}</p>
  <div class="tblwrap"><table><thead><tr><th>Return</th><th>Item</th><th class="n">Qty</th><th>Condition</th><th>Restock</th></tr></thead><tbody>${lines.map((l,i)=>`<tr><td><input type="checkbox" id="rt_on_${i}" onchange="retCalc('${invId}')"></td><td>${esc(l.name)} <span class="muted">${money(lineRevenue(inv,l)/l.qty)} ea</span> ${trialInfo(l)}${l.asIs?' <span class="tag bad">sold as-is</span>':""}${l.floorSample?' <span class="tag warn">floor sample</span>':""}</td><td class="n"><input type="number" id="rt_q_${i}" min="1" max="${l.qty-(returned[l.lineId]||0)}" value="${l.qty-(returned[l.lineId]||0)}" style="width:64px" onchange="retCalc('${invId}')"></td><td><select id="rt_c_${i}" onchange="document.getElementById('rt_s_${i}').checked=this.value!=='damaged';retCalc('${invId}')"><option value="new">Unopened / like new</option><option value="opened">Used / opened</option><option value="damaged">Damaged / defective</option></select></td><td><input type="checkbox" id="rt_s_${i}" checked></td></tr>`).join("")}</tbody></table></div>
  <div class="grid g3" style="margin-top:12px"><div class="field"><label class="f">Reason</label><select id="rt_reason" onchange="retCalc('${invId}')">${optsList(["Changed mind","Comfort exchange","Defective","Damaged in delivery","Wrong item","Other"],"Changed mind")}</select></div><div class="field"><label class="f">Fee</label><input type="number" step="0.01" id="rt_fee" value="0" onchange="retCalc('${invId}')"></div><div class="field"><label class="f">Refund to</label><select id="rt_method">${optsList(["Original payment","Store credit","Exchange credit (open new sale)"],"Original payment")}</select></div></div>
  <div class="field"><label class="f">Notes</label><input type="text" id="rt_notes"></div>
  <div id="rt_summary" class="suggest"></div>
  <div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="doReturn('${invId}')">Process return</button></div>`,true);
  window._retLines=lines; window._feeTouched=false; retCalc(invId);
}
function retCalc(invId){
  const inv=byId("invoices",invId); const st=storeSettings(); const lines=window._retLines||[]; const reason=fv("rt_reason"); let sub=0,cost=0,n=0; const feeEl=document.getElementById("rt_fee");
  lines.forEach((l,i)=>{ if(!fchk("rt_on_"+i)) return; const q=Math.max(1,Math.min(l.qty,fnum("rt_q_"+i))); sub+=lineRevenue(inv,l)/l.qty*q; cost+=l.cost*q; n++; });
  if(!window._feeTouched){ if(reason==="Comfort exchange") feeEl.value=st.comfortExchangeFee; else if(reason==="Changed mind") feeEl.value=round2(sub*st.restockPct/100); else feeEl.value=0; }
  const fee=fnum("rt_fee"); const rate=inv.taxExempt?0:(inv.taxRate??st.taxRate); const tax=round2(sub*rate/100); const total=round2(sub+tax-fee);
  let warn=""; lines.forEach((l,i)=>{ if(fchk("rt_on_"+i)&&l.asIs) warn+=`${l.name} was sold as-is (all sales final). `; });
  if(reason==="Comfort exchange"){ const sel=lines.filter((l,i)=>fchk("rt_on_"+i)); if(sel.some(l=>!l.mattress)) warn+="Comfort exchanges apply to mattresses only. "; if(st.protectorRequired&&!inv.lines.some(isProtector)) warn+="No mattress protector on this invoice — policy requires one. "; sel.forEach(l=>{ const start=l.deliveredAt||(inv.delivery?null:inv.date); if(!start) warn+=`${l.name} hasn't been delivered yet. `; else if(addDays(start,st.trialNights)<todayISO()) warn+=`${l.name} is past its ${st.trialNights}-night trial. `; }); const m=document.getElementById("rt_method"); if(m&&!m.dataset.set){ m.value="Exchange credit (open new sale)"; m.dataset.set="1"; } }
  document.getElementById("rt_summary").innerHTML=`<div class="tot"><span>${n} line${n===1?"":"s"} · merchandise</span><b>${money(sub)}</b></div><div class="tot"><span>Tax refunded</span><span>${money(tax)}</span></div><div class="tot"><span>Fee</span><span>-${money(fee)}</span></div><div class="tot grand" style="font-size:18px"><span>Refund</span><span>${money(total)}</span></div>${warn?`<div class="notice" style="margin:8px 0 0">${esc(warn)}${isManager()?"":" Manager approval will be requested."}</div>`:""}`;
  window._retCalc={sub:round2(sub),cost:round2(cost),tax,fee,total,warn};
}
document.addEventListener("input",e=>{ if(e.target&&e.target.id==="rt_fee") window._feeTouched=true; });
async function doReturn(invId,force){ if(!requirePerm("returns","process returns and refunds")) return;
  const inv=byId("invoices",invId); const R=window._retCalc; const lines=window._retLines||[]; const sel=[]; lines.forEach((l,i)=>{ if(fchk("rt_on_"+i)) sel.push({lineId:l.lineId,productId:l.productId,name:l.name,qty:Math.max(1,Math.min(l.qty,fnum("rt_q_"+i))),condition:fv("rt_c_"+i),restock:fchk("rt_s_"+i),unitRefund:round2(lineRevenue(inv,l)/l.qty),cost:l.cost,mattress:!!l.mattress}); });
  if(!sel.length) return toast("Tick at least one item.",true);
  if(R.warn&&!has("approve")&&!force) return managerOverride("This return is outside policy: "+R.warn,()=>doReturn(invId,true));
  const method=fv("rt_method"); const c=byId("customers",inv.customerId);
  const ret={id:uid(),number:nextNumber("nextReturn","RET"),invoiceId:invId,customerId:inv.customerId,date:todayISO(),reason:fv("rt_reason"),lines:sel,refundSub:R.sub,refundTax:R.tax,fee:R.fee,refundTotal:R.total,costBack:round2(sel.filter(l=>l.restock).reduce((a,l)=>a+l.cost*l.qty,0)),method,notes:fv("rt_notes"),by:session.staffId,salesId:inv.salesId};
  for(const l of sel){ if(l.restock&&l.productId){ const p=byId("products",l.productId); if(p&&p.isKit){ for(const k of (p.kitItems||[])){ const cp=byId("products",k.productId); if(cp){ stockMove(cp,k.qty*l.qty,undefined); await save("products",cp); } } continue; } if(p){ stockMove(p,l.qty,undefined); if(l.condition!=="new"&&!p.floorSample){ p.floorSample=true; p.floorSampleSince=todayISO(); } await save("products",p); } } }
  if(method==="Store credit"&&c){ c.credit=round2((c.credit||0)+R.total); await save("customers",c); logAudit("credit",`Store credit +${money(R.total)} for ${c.name} (return ${R.number})`,{invoiceId:invId,amount:R.total}); }
  logAudit("return",`${R.number} on ${inv.number}: refund ${money(R.total)} by ${method}`,{invoiceId:invId,amount:R.total});
  await save("returns",ret); await save("invoices",inv); window._feeTouched=false; closeModal();
  if(method.startsWith("Exchange")){ cur=newInvoice(); cur.customerId=inv.customerId; cur.taxExempt=!!inv.taxExempt; cur.salesId=inv.salesId; cur.payments=[{method:"Exchange credit "+ret.number,amount:R.total,date:todayISO(),by:session.staffId}]; cur.notes=`Exchange for ${inv.number}`; if(ret.reason==="Comfort exchange"){ cur.delivery=true; cur.deliveryFee=0; } go("pos"); toast(`Return ${ret.number} processed — ${money(R.total)} credit applied to the new sale`); }
  else { render(); toast(`Return ${ret.number} processed — refund ${money(R.total)} by ${method.toLowerCase()}`); printReturn(ret.id); }
}
function printReturn(id){ const r=byId("returns",id); const st=storeSettings(); const inv=byId("invoices",r.invoiceId); printHTML(`<div class="page"><h1>${esc(st.name)}</h1><h2>Return ${esc(r.number)}</h2><p>${dateFmt(r.date)} · original invoice ${esc(inv?.number||"")} · ${esc(custName(r.customerId))}</p><table class="ptable"><tr><th>Item</th><th class="n">Qty</th><th>Condition</th><th class="n">Refund</th></tr>${r.lines.map(l=>`<tr><td>${esc(l.name)}</td><td class="n">${l.qty}</td><td>${esc(l.condition)}</td><td class="n">${money(l.unitRefund*l.qty)}</td></tr>`).join("")}<tr><td colspan="3" class="n">Tax</td><td class="n">${money(r.refundTax)}</td></tr>${r.fee?`<tr><td colspan="3" class="n">${r.reason==="Comfort exchange"?"Comfort exchange fee":"Restocking fee"}</td><td class="n">-${money(r.fee)}</td></tr>`:""}<tr><td colspan="3" class="n"><b>Refund (${esc(r.method)})</b></td><td class="n"><b>${money(r.refundTotal)}</b></td></tr></table><p style="margin-top:10px">Reason: ${esc(r.reason)}. ${esc(r.notes||"")}</p><p style="margin-top:30px">Customer signature: ______________________</p></div>`); }
function newClaim(customerId,invoiceId){
  const inv=byId("invoices",invoiceId); const lines=inv?inv.lines.filter(l=>l.productId):[];
  modal(`<h2>Warranty claim</h2><div class="grid g2"><div class="field"><label class="f">Customer</label><select id="wc_c" onchange="claimInvOpts(this.value)">${opts(S.customers,customerId||"",x=>x.name,x=>x.id,"Choose…")}</select></div><div class="field"><label class="f">Invoice</label><select id="wc_i" onchange="claimLineOpts(this.value)">${opts(S.invoices.filter(i=>i.customerId===(customerId||"")&&!["void","quote"].includes(i.status)),invoiceId||"",x=>x.number+" · "+dateShort(x.date),x=>x.id,"—")}</select></div></div>
  <div class="field"><label class="f">Item</label><select id="wc_l">${opts(lines,"",l=>l.name,l=>l.lineId,"Choose item…")}</select></div>
  <div class="grid g2"><div class="field"><label class="f">Issue</label><select id="wc_issue">${optsList(["Sagging / body impression","Broken frame or mechanism","Fabric / leather defect","Seam or stitching failure","Adjustable base motor","Cushion collapse","Other"],"Other")}</select></div><div class="field"><label class="f">Date noticed</label><input type="date" id="wc_d" value="${todayISO()}"></div></div>
  <div class="field"><label class="f">Details (measurements, photos taken, etc.)</label><textarea id="wc_notes" rows="3"></textarea></div>
  <div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="saveClaim()">Create claim</button></div>`);
}
function claimInvOpts(cid){ const sel=document.getElementById("wc_i"); sel.innerHTML=opts(S.invoices.filter(i=>i.customerId===cid&&!["void","quote"].includes(i.status)),"",x=>x.number+" · "+dateShort(x.date),x=>x.id,"—"); claimLineOpts(""); }
function claimLineOpts(iid){ const inv=byId("invoices",iid); document.getElementById("wc_l").innerHTML=opts(inv?inv.lines.filter(l=>l.productId):[],"",l=>l.name,l=>l.lineId,"Choose item…"); }
async function saveClaim(){ const cid=fv("wc_c"); if(!cid) return toast("Choose a customer.",true); const inv=byId("invoices",fv("wc_i")); const line=inv?.lines.find(l=>l.lineId===fv("wc_l")); const p=line?byId("products",line.productId):null; const start=line?(line.deliveredAt||inv.date):""; const exp=line&&line.warrantyYears?addDays(start,Math.round(line.warrantyYears*365)):"";
  if(line&&line.asIs&&!confirm("This item was sold as-is with no warranty. Open the claim anyway?")) return;
  const cl=await save("claims",{id:uid(),number:nextNumber("nextClaim","WC"),customerId:cid,invoiceId:inv?.id||"",lineId:line?.lineId||"",productId:p?.id||"",itemName:line?.name||"(item not on file)",vendorId:p?.vendorId||"",issue:fv("wc_issue"),date:fv("wc_d")||todayISO(),notes:fv("wc_notes"),status:"open",warrantyEnd:exp,log:[{date:todayISO(),by:session.staffId,text:"Claim opened"+(exp?(exp>=todayISO()?" — in warranty until "+dateShort(exp):" — WARRANTY EXPIRED "+dateShort(exp)):"")}]});
  closeModal(); serviceTab="claims"; go("service"); toast("Claim "+cl.number+" created"+(exp&&exp<todayISO()?" — note: warranty has expired":"")); }
function openClaim(id){ const x=byId("claims",id); const v=byId("vendors",x.vendorId); const c=byId("customers",x.customerId);
  modal(`<h2>${esc(x.number)} ${statusTag(x.status)}</h2><p><b>${esc(c?.name||"")}</b> · ${esc(x.itemName)} · ${esc(x.issue)}<br><span class="muted">${x.warrantyEnd?`Warranty ${x.warrantyEnd>=todayISO()?"valid to":"expired"} ${dateShort(x.warrantyEnd)} · `:""}vendor ${esc(v?.name||"—")}${v?.email?` · <a href="mailto:${esc(v.email)}?subject=${encodeURIComponent("Warranty claim "+x.number+" — "+x.itemName)}&body=${encodeURIComponent(`Claim ${x.number}\nCustomer: ${c?.name}\nItem: ${x.itemName}\nIssue: ${x.issue}\n${x.notes||""}`)}">email vendor</a>`:""}</span></p>
  <div class="timeline">${(x.log||[]).map(l=>`<div><span class="muted">${dateShort(l.date)} · ${esc(staffName(l.by))}</span> — ${esc(l.text)}</div>`).join("")}</div>
  <div class="grid g2"><div class="field"><label class="f">Update status</label><select id="cl_st">${optsList(["open","sent to vendor","approved","denied","replaced","repaired","credited","closed"],x.status)}</select></div><div class="field"><label class="f">Note</label><input type="text" id="cl_note"></div></div>
  <div class="actions"><button class="btn" onclick="closeModal()">Close</button>${["approved","replaced"].includes(x.status)&&x.productId?`<button class="btn" onclick="closeModal();cur=newInvoice();cur.customerId='${x.customerId}';addLine('${x.productId}');const l=cur.lines[0];l.price=0;cur.notes='Warranty replacement — claim ${x.number}';cur.delivery=true;cur.deliveryFee=0;go('pos')">Ring replacement at $0</button>`:""}<button class="btn p" onclick="(async()=>{const x=byId('claims','${id}');x.status=fv('cl_st');(x.log=x.log||[]).push({date:todayISO(),by:session.staffId,text:(fv('cl_note')||'Status → '+fv('cl_st'))});await save('claims',x);closeModal();render()})()">Save update</button></div>`);
}
